window.QBANK = window.QBANK || {};
window.QBANK["sma-fisika"] = {
  level: "SMA", subject: "Fisika", duration: 900,
  questions: [
    { q: "Sebuah mobil bergerak dengan kecepatan $20\\ \\text{m/s}$. Jarak tempuh dalam $5$ sekon adalah ...", options: ["40 m", "100 m", "25 m", "4 m"], answer: 1, solution: "Langkah 1: diketahui $v = 20\\ \\text{m/s}$ dan $t = 5\\ \\text{s}$. Langkah 2: karena kecepatan tetap, gunakan rumus gerak lurus beraturan $s = v \\times t$. Langkah 3: $s = 20 \\times 5 = 100\\ \\text{m}$." },
    { q: "Sebuah benda mula-mula diam, lalu dipercepat beraturan $2\\ \\text{m/s}^2$ selama $4$ sekon. Kecepatan akhir benda adalah ...", options: ["4 m/s", "8 m/s", "6 m/s", "2 m/s"], answer: 1, solution: "Langkah 1: diketahui $v_0 = 0$, $a = 2\\ \\text{m/s}^2$, $t = 4\\ \\text{s}$. Langkah 2: gunakan rumus GLBB $v_t = v_0 + at$. Langkah 3: $v_t = 0 + (2)(4) = 8\\ \\text{m/s}$." },
    { q: "Sebuah benda bermassa $5\\ \\text{kg}$ bergerak dengan percepatan $3\\ \\text{m/s}^2$. Besar gaya yang bekerja pada benda adalah ...", options: ["8 N", "1,67 N", "15 N", "2 N"], answer: 2, solution: "Langkah 1: diketahui $m = 5\\ \\text{kg}$ dan $a = 3\\ \\text{m/s}^2$. Langkah 2: gunakan Hukum II Newton $F = m \\times a$. Langkah 3: $F = 5 \\times 3 = 15\\ \\text{N}$." },
    { q: "Sebuah benda bermassa $2\\ \\text{kg}$ bergerak dengan kecepatan $10\\ \\text{m/s}$. Energi kinetik benda tersebut adalah ...", options: ["50 J", "200 J", "100 J", "20 J"], answer: 2, solution: "Langkah 1: diketahui $m = 2\\ \\text{kg}$ dan $v = 10\\ \\text{m/s}$. Langkah 2: gunakan rumus $E_k = \\frac{1}{2}mv^2$. Langkah 3: $E_k = \\frac{1}{2}(2)(10^2) = \\frac{1}{2}(2)(100) = 100\\ \\text{J}$." },
    { q: "Sebuah benda bermassa $4\\ \\text{kg}$ berada pada ketinggian $5\\ \\text{m}$ dari tanah ($g = 10\\ \\text{m/s}^2$). Energi potensial benda adalah ...", options: ["200 J", "100 J", "20 J", "40 J"], answer: 0, solution: "Langkah 1: diketahui $m = 4\\ \\text{kg}$, $h = 5\\ \\text{m}$, $g = 10\\ \\text{m/s}^2$. Langkah 2: gunakan rumus $E_p = mgh$. Langkah 3: $E_p = 4 \\times 10 \\times 5 = 200\\ \\text{J}$." },
    { q: "Sebuah buku diam di atas meja. Hal ini menunjukkan bahwa ...", options: ["gaya gravitasi tidak bekerja pada buku", "resultan gaya pada buku sama dengan nol", "massa buku sama dengan nol", "tidak ada gaya normal dari meja"], answer: 1, solution: "Langkah 1: buku diam artinya kecepatannya tetap (nol). Langkah 2: menurut Hukum I Newton, benda mempertahankan keadaan diamnya jika resultan gaya yang bekerja padanya nol. Langkah 3: gaya berat ke bawah diimbangi gaya normal ke atas, sehingga resultan gayanya nol." },
    { q: "Sebuah lampu dihubungkan ke tegangan $12\\ \\text{V}$ dan memiliki hambatan $4\\ \\Omega$. Kuat arus yang mengalir adalah ...", options: ["48 A", "0,33 A", "3 A", "16 A"], answer: 2, solution: "Langkah 1: diketahui $V = 12\\ \\text{V}$ dan $R = 4\\ \\Omega$. Langkah 2: gunakan Hukum Ohm $I = \\frac{V}{R}$. Langkah 3: $I = \\frac{12}{4} = 3\\ \\text{A}$." },
    { q: "Sebuah alat listrik dipasang pada tegangan $220\\ \\text{V}$ dan dialiri arus $0{,}5\\ \\text{A}$. Daya listrik alat tersebut adalah ...", options: ["440 W", "220 W", "110 W", "55 W"], answer: 2, solution: "Langkah 1: diketahui $V = 220\\ \\text{V}$ dan $I = 0{,}5\\ \\text{A}$. Langkah 2: gunakan rumus daya $P = V \\times I$. Langkah 3: $P = 220 \\times 0{,}5 = 110\\ \\text{W}$." },
    { q: "Sebuah gaya $20\\ \\text{N}$ mendorong benda searah perpindahan sejauh $5\\ \\text{m}$. Besar usaha yang dilakukan gaya tersebut adalah ...", options: ["25 J", "4 J", "1000 J", "100 J"], answer: 3, solution: "Langkah 1: diketahui $F = 20\\ \\text{N}$ searah perpindahan dan $s = 5\\ \\text{m}$. Langkah 2: gunakan rumus usaha $W = F \\times s$. Langkah 3: $W = 20 \\times 5 = 100\\ \\text{J}$." },
    { q: "Dua hambatan $2\\ \\Omega$ dan $3\\ \\Omega$ dirangkai seri lalu dihubungkan ke tegangan $10\\ \\text{V}$. Kuat arus yang mengalir adalah ...", options: ["5 A", "0,5 A", "10 A", "2 A"], answer: 3, solution: "Langkah 1: rangkaian seri, jadi $R_{tot} = R_1 + R_2 = 2 + 3 = 5\\ \\Omega$. Langkah 2: gunakan Hukum Ohm $I = \\frac{V}{R_{tot}} = \\frac{10}{5}$. Langkah 3: $I = 2\\ \\text{A}$." },
    { q: "Di antara besaran berikut, yang termasuk besaran pokok adalah ...", options: ["kecepatan", "gaya", "suhu", "energi"], answer: 2, solution: "Langkah 1: besaran pokok adalah besaran yang satuannya ditetapkan terlebih dahulu (panjang, massa, waktu, suhu, kuat arus, jumlah zat, intensitas cahaya). Langkah 2: kecepatan, gaya, dan energi diturunkan dari besaran pokok sehingga termasuk besaran turunan. Langkah 3: jadi yang termasuk besaran pokok adalah suhu." },
    { q: "Satuan gaya dalam Sistem Internasional (SI) adalah ...", options: ["joule", "watt", "newton", "pascal"], answer: 2, solution: "Langkah 1: gaya dirumuskan $F = m \\times a$ dengan satuan $\\text{kg} \\cdot \\text{m/s}^2$. Langkah 2: satuan ini diberi nama newton (N). Langkah 3: joule untuk energi, watt untuk daya, dan pascal untuk tekanan." },
    { q: "Sebuah benda jatuh bebas dari ketinggian $20\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Waktu yang dibutuhkan benda sampai ke tanah adalah ...", options: ["$1$ s", "$2$ s", "$4$ s", "$\\sqrt{2}$ s"], answer: 1, solution: "Langkah 1: diketahui $h = 20\\ \\text{m}$, $v_0 = 0$, $g = 10\\ \\text{m/s}^2$. Langkah 2: gunakan $h = \\frac{1}{2}gt^2$, sehingga $20 = \\frac{1}{2}(10)t^2 = 5t^2$. Langkah 3: $t^2 = 4$, jadi $t = 2\\ \\text{s}$." },
    { q: "Sebuah mobil melaju $20\\ \\text{m/s}$ lalu direm dengan perlambatan $4\\ \\text{m/s}^2$. Waktu hingga mobil berhenti adalah ...", options: ["$4$ s", "$5$ s", "$8$ s", "$10$ s"], answer: 1, solution: "Langkah 1: diketahui $v_0 = 20\\ \\text{m/s}$, $a = -4\\ \\text{m/s}^2$, $v_t = 0$. Langkah 2: gunakan $v_t = v_0 + at$, sehingga $0 = 20 - 4t$. Langkah 3: $4t = 20$, jadi $t = 5\\ \\text{s}$." },
    { q: "Berat sebuah benda bermassa $3\\ \\text{kg}$ adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["$3$ N", "$30$ N", "$0{,}3$ N", "$13$ N"], answer: 1, solution: "Langkah 1: diketahui $m = 3\\ \\text{kg}$ dan $g = 10\\ \\text{m/s}^2$. Langkah 2: gunakan rumus berat $w = m \\times g$. Langkah 3: $w = 3 \\times 10 = 30\\ \\text{N}$." },
    { q: "Saat kamu mendorong dinding, dinding mendorongmu kembali dengan gaya sama besar berlawanan arah. Peristiwa ini contoh Hukum Newton ...", options: ["I", "II", "III", "gravitasi"], answer: 2, solution: "Langkah 1: ada dua gaya yang berpasangan: gaya aksi (kamu mendorong dinding) dan gaya reaksi (dinding mendorongmu). Langkah 2: Hukum III Newton menyatakan setiap aksi menimbulkan reaksi yang sama besar dan berlawanan arah. Langkah 3: jadi peristiwa ini contoh Hukum III Newton." },
    { q: "Sebuah benda bermassa $2\\ \\text{kg}$ dijatuhkan dari ketinggian $10\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Kecepatan benda saat menyentuh tanah adalah ...", options: ["$10$ m/s", "$10\\sqrt{2}$ m/s", "$20$ m/s", "$14$ m/s"], answer: 1, solution: "Langkah 1: gunakan kekekalan energi mekanik, $E_{p\\ \\text{awal}} = E_{k\\ \\text{akhir}}$. Langkah 2: $mgh = \\frac{1}{2}mv^2$, massa saling meniadakan, $v = \\sqrt{2gh} = \\sqrt{2 \\times 10 \\times 10} = \\sqrt{200}$. Langkah 3: $\\sqrt{200} = 10\\sqrt{2}\\ \\text{m/s}$." },
    { q: "Sebuah mesin melakukan usaha $600\\ \\text{J}$ dalam waktu $3$ sekon. Daya mesin tersebut adalah ...", options: ["$1800$ W", "$200$ W", "$603$ W", "$20$ W"], answer: 1, solution: "Langkah 1: diketahui $W = 600\\ \\text{J}$ dan $t = 3\\ \\text{s}$. Langkah 2: gunakan rumus daya $P = \\frac{W}{t}$. Langkah 3: $P = \\frac{600}{3} = 200\\ \\text{W}$." },
    { q: "Sebuah benda bermassa $4\\ \\text{kg}$ bergerak dengan kecepatan $5\\ \\text{m/s}$. Momentum benda tersebut adalah ...", options: ["$9$ kg m/s", "$20$ kg m/s", "$0{,}8$ kg m/s", "$45$ kg m/s"], answer: 1, solution: "Langkah 1: diketahui $m = 4\\ \\text{kg}$ dan $v = 5\\ \\text{m/s}$. Langkah 2: gunakan rumus momentum $p = m \\times v$. Langkah 3: $p = 4 \\times 5 = 20\\ \\text{kg m/s}$." },
    { q: "Sebuah gaya $50\\ \\text{N}$ bekerja pada benda selama $0{,}2$ sekon. Besar impuls gaya tersebut adalah ...", options: ["$250$ N s", "$10$ N s", "$50{,}2$ N s", "$5$ N s"], answer: 1, solution: "Langkah 1: diketahui $F = 50\\ \\text{N}$ dan $\\Delta t = 0{,}2\\ \\text{s}$. Langkah 2: gunakan rumus impuls $I = F \\times \\Delta t$. Langkah 3: $I = 50 \\times 0{,}2 = 10\\ \\text{N s}$." },
    { q: "Tekanan hidrostatis pada kedalaman $2\\ \\text{m}$ di dalam air adalah ... ($\\rho_{air} = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$)", options: ["$2000$ Pa", "$20000$ Pa", "$5000$ Pa", "$200$ Pa"], answer: 1, solution: "Langkah 1: diketahui $\\rho = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$, $h = 2\\ \\text{m}$. Langkah 2: gunakan $P = \\rho g h$. Langkah 3: $P = 1000 \\times 10 \\times 2 = 20000\\ \\text{Pa}$." },
    { q: "Sebuah benda dapat terapung di permukaan fluida jika ...", options: ["massa jenis benda lebih besar dari massa jenis fluida", "massa jenis benda sama dengan massa jenis fluida", "massa jenis benda lebih kecil dari massa jenis fluida", "volume benda lebih besar dari volume fluida"], answer: 2, solution: "Langkah 1: benda terapung saat gaya ke atas (Archimedes) mampu menahan berat benda. Langkah 2: hal ini terjadi ketika massa jenis rata-rata benda lebih kecil dari massa jenis fluida. Langkah 3: jadi syarat terapung adalah massa jenis benda lebih kecil dari massa jenis fluida." },
    { q: "Gelombang merambat dengan cepat rambat $340\\ \\text{m/s}$ dan frekuensi $170\\ \\text{Hz}$. Panjang gelombangnya adalah ...", options: ["$0{,}5$ m", "$2$ m", "$510$ m", "$4$ m"], answer: 1, solution: "Langkah 1: diketahui $v = 340\\ \\text{m/s}$ dan $f = 170\\ \\text{Hz}$. Langkah 2: gunakan $v = \\lambda \\times f$, sehingga $\\lambda = \\frac{v}{f}$. Langkah 3: $\\lambda = \\frac{340}{170} = 2\\ \\text{m}$." },
    { q: "Sebuah bandul bergetar $20$ kali dalam $4$ sekon. Frekuensi getaran bandul adalah ...", options: ["$80$ Hz", "$5$ Hz", "$0{,}2$ Hz", "$24$ Hz"], answer: 1, solution: "Langkah 1: diketahui jumlah getaran $n = 20$ dan waktu $t = 4\\ \\text{s}$. Langkah 2: gunakan $f = \\frac{n}{t}$. Langkah 3: $f = \\frac{20}{4} = 5\\ \\text{Hz}$." },
    { q: "Dua benda bermuatan listrik sejenis didekatkan satu sama lain. Keduanya akan ...", options: ["saling tarik-menarik", "saling tolak-menolak", "tidak saling memengaruhi", "menyatu menjadi satu"], answer: 1, solution: "Langkah 1: muatan listrik sejenis artinya keduanya positif atau keduanya negatif. Langkah 2: sesuai sifat muatan listrik, muatan sejenis tolak-menolak sedangkan muatan berlawanan jenis tarik-menarik. Langkah 3: jadi keduanya saling tolak-menolak." },
    { q: "Jarak antara dua muatan listrik dijadikan dua kali semula. Besar gaya Coulomb yang terjadi menjadi ...", options: ["$2$ kali semula", "$4$ kali semula", "$\\frac{1}{2}$ kali semula", "$\\frac{1}{4}$ kali semula"], answer: 3, solution: "Langkah 1: Hukum Coulomb $F = k\\frac{q_1 q_2}{r^2}$, gaya berbanding terbalik dengan kuadrat jarak. Langkah 2: jika $r$ menjadi $2r$, maka $F' = \\frac{F}{2^2} = \\frac{F}{4}$. Langkah 3: jadi gaya menjadi $\\frac{1}{4}$ kali semula." },
    { q: "Dua hambatan masing-masing $6\\ \\Omega$ dirangkai paralel. Hambatan penggantinya adalah ...", options: ["$12\\ \\Omega$", "$3\\ \\Omega$", "$36\\ \\Omega$", "$1\\ \\Omega$"], answer: 1, solution: "Langkah 1: untuk rangkaian paralel, $\\frac{1}{R_p} = \\frac{1}{R_1} + \\frac{1}{R_2}$. Langkah 2: $\\frac{1}{R_p} = \\frac{1}{6} + \\frac{1}{6} = \\frac{2}{6} = \\frac{1}{3}$. Langkah 3: $R_p = 3\\ \\Omega$." },
    { q: "Sebuah lampu $60\\ \\text{W}$ dinyalakan selama $5$ jam. Energi listrik yang digunakan adalah ...", options: ["$300$ J", "$1080$ kJ", "$12$ kJ", "$300$ kJ"], answer: 1, solution: "Langkah 1: diketahui $P = 60\\ \\text{W}$ dan $t = 5$ jam $= 5 \\times 3600 = 18000$ sekon. Langkah 2: gunakan $W = P \\times t = 60 \\times 18000$. Langkah 3: $W = 1080000\\ \\text{J} = 1080\\ \\text{kJ}$." },
    { q: "Bahan yang dapat ditarik dengan kuat oleh magnet disebut bahan ...", options: ["diamagnetik", "paramagnetik", "feromagnetik", "nonmagnetik"], answer: 2, solution: "Langkah 1: berdasarkan sifat kemagnetannya, bahan dibagi menjadi tiga. Langkah 2: feromagnetik ditarik kuat oleh magnet (contoh besi, baja, nikel), paramagnetik ditarik lemah, diamagnetik ditolak lemah. Langkah 3: jadi jawabannya feromagnetik." },
    { q: "Di luar magnet, arah garis gaya magnet adalah ...", options: ["dari kutub selatan ke kutub utara", "dari kutub utara ke kutub selatan", "melingkar tanpa arah tertentu", "dari tengah magnet ke tepi"], answer: 1, solution: "Langkah 1: garis gaya magnet adalah garis khayal yang menggambarkan medan magnet. Langkah 2: di luar magnet, garis gaya keluar dari kutub utara dan masuk ke kutub selatan. Langkah 3: jadi arahnya dari kutub utara ke kutub selatan." },
    { q: "Sebuah benda diletakkan $3$ m di depan cermin datar. Jarak benda ke bayangannya adalah ...", options: ["$3$ m", "$6$ m", "$1{,}5$ m", "$9$ m"], answer: 1, solution: "Langkah 1: sifat cermin datar, jarak bayangan ke cermin sama dengan jarak benda ke cermin, yaitu $3$ m di belakang cermin. Langkah 2: benda dan bayangan terletak di sisi berlawanan dari cermin. Langkah 3: jarak benda ke bayangan $= 3 + 3 = 6$ m. (Catatan: bayangannya maya, tegak, sama besar.)" },
    { q: "Sebuah benda diletakkan $30$ cm di depan cermin cekung yang jarak fokusnya $10$ cm. Jarak bayangan yang terbentuk adalah ...", options: ["$7{,}5$ cm", "$15$ cm", "$20$ cm", "$40$ cm"], answer: 1, solution: "Langkah 1: gunakan rumus cermin $\\frac{1}{f} = \\frac{1}{s} + \\frac{1}{s'}$ dengan $f = 10$ cm dan $s = 30$ cm. Langkah 2: $\\frac{1}{s'} = \\frac{1}{10} - \\frac{1}{30} = \\frac{3-1}{30} = \\frac{2}{30} = \\frac{1}{15}$. Langkah 3: $s' = 15$ cm, bayangan nyata di depan cermin. (Catatan: yang dijumlahkan adalah kebalikannya, bukan langsung $30 - 10$.)" },
    { q: "Sebuah benda diletakkan $45$ cm di depan lensa cembung berjarak fokus $15$ cm. Jarak bayangan dari lensa adalah ...", options: ["$11{,}25$ cm", "$22{,}5$ cm", "$30$ cm", "$60$ cm"], answer: 1, solution: "Langkah 1: gunakan rumus lensa $\\frac{1}{f} = \\frac{1}{s} + \\frac{1}{s'}$ dengan $f = 15$ cm dan $s = 45$ cm. Langkah 2: $\\frac{1}{s'} = \\frac{1}{15} - \\frac{1}{45} = \\frac{3-1}{45} = \\frac{2}{45}$. Langkah 3: $s' = \\frac{45}{2} = 22{,}5$ cm, bayangan nyata, terbalik, diperkecil." },
    { q: "Sebuah benda diletakkan $24$ cm di depan lensa cekung yang jarak fokusnya $12$ cm. Letak bayangan yang terbentuk adalah ...", options: ["$8$ cm di depan lensa (maya)", "$8$ cm di belakang lensa (nyata)", "$24$ cm di depan lensa", "$36$ cm di depan lensa"], answer: 0, solution: "Langkah 1: lensa cekung bersifat divergen, jadi $f = -12$ cm (negatif). Gunakan $\\frac{1}{f} = \\frac{1}{s} + \\frac{1}{s'}$. Langkah 2: $\\frac{1}{s'} = \\frac{1}{-12} - \\frac{1}{24} = \\frac{-2-1}{24} = \\frac{-3}{24} = -\\frac{1}{8}$. Langkah 3: $s' = -8$ cm, tanda negatif artinya bayangan maya, tegak, diperkecil, $8$ cm di depan lensa (sisi yang sama dengan benda)." },
    { q: "Sebuah lup berjarak fokus $5$ cm digunakan oleh mata normal (titik dekat $25$ cm). Perbesaran maksimum lup (mata berakomodasi maksimum) adalah ...", options: ["$5$ kali", "$6$ kali", "$4$ kali", "$25$ kali"], answer: 1, solution: "Langkah 1: perbesaran maksimum lup terjadi saat mata berakomodasi maksimum, rumusnya $M = \\frac{S_n}{f} + 1$. Langkah 2: $S_n = 25$ cm dan $f = 5$ cm, sehingga $M = \\frac{25}{5} + 1$. Langkah 3: $M = 5 + 1 = 6$ kali. (Catatan: $5$ kali adalah perbesaran saat mata tidak berakomodasi.)" },
    { q: "Suatu gas menerima kalor sebesar $500$ J dan melakukan usaha sebesar $200$ J. Perubahan energi dalam gas tersebut adalah ...", options: ["$700$ J", "$300$ J", "$-300$ J", "$2{,}5$ J"], answer: 1, solution: "Langkah 1: gunakan Hukum I Termodinamika $\\Delta U = Q - W$ (dengan $W$ usaha yang dilakukan sistem). Langkah 2: $Q = +500$ J (menerima kalor) dan $W = +200$ J (melakukan usaha). Langkah 3: $\\Delta U = 500 - 200 = 300$ J, energi dalam bertambah." },
    { q: "Pada proses isotermik (suhu tetap), pernyataan yang benar adalah ...", options: ["perubahan energi dalam gas sama dengan nol", "kalor yang terlibat sama dengan nol", "tekanan gas selalu tetap", "volume gas selalu tetap"], answer: 0, solution: "Langkah 1: proses isotermik artinya suhu $T$ tetap. Langkah 2: energi dalam gas ideal hanya bergantung pada suhu, sehingga $\\Delta U = 0$. Langkah 3: dari Hukum I, $0 = Q - W$ sehingga $Q = W$; kalor seluruhnya berubah menjadi usaha. (Catatan: proses yang kalornya nol disebut adiabatik, bukan isotermik.)" },
    { q: "Suatu gas dimampatkan secara adiabatik sehingga usaha sebesar $300$ J dilakukan pada gas. Perubahan energi dalam gas adalah ...", options: ["$-300$ J", "$300$ J", "$0$ J", "$600$ J"], answer: 1, solution: "Langkah 1: proses adiabatik artinya tidak ada kalor yang terlibat, $Q = 0$. Langkah 2: usaha dilakukan pada gas (gas dimampatkan), jadi $W = -300$ J menurut konvensi usaha oleh sistem. Langkah 3: $\\Delta U = Q - W = 0 - (-300) = 300$ J, energi dalam gas bertambah $300$ J." },
    { q: "Sebuah mesin Carnot bekerja antara suhu $600$ K dan $300$ K. Efisiensi mesin tersebut adalah ...", options: ["$25\\%$", "$50\\%$", "$100\\%$", "$200\\%$"], answer: 1, solution: "Langkah 1: gunakan rumus efisiensi Carnot $\\eta = \\left(1 - \\frac{T_2}{T_1}\\right) \\times 100\\%$. Langkah 2: $T_1 = 600$ K (reservoir panas) dan $T_2 = 300$ K (reservoir dingin). Langkah 3: $\\eta = \\left(1 - \\frac{300}{600}\\right) \\times 100\\% = (1 - 0{,}5) \\times 100\\% = 50\\%$. (Catatan: suhu harus dalam kelvin.)" },
    { q: "Sebuah mesin Carnot menyerap kalor dari reservoir bersuhu $500$ K dan membuang kalor ke reservoir bersuhu $400$ K. Efisiensi mesin tersebut adalah ...", options: ["$80\\%$", "$20\\%$", "$25\\%$", "$125\\%$"], answer: 1, solution: "Langkah 1: gunakan $\\eta = \\left(1 - \\frac{T_2}{T_1}\\right) \\times 100\\%$. Langkah 2: $T_1 = 500$ K dan $T_2 = 400$ K. Langkah 3: $\\eta = \\left(1 - \\frac{400}{500}\\right) \\times 100\\% = (1 - 0{,}8) \\times 100\\% = 20\\%$. (Catatan: efisiensi tidak mungkin $100\\%$ atau lebih, sesuai Hukum II Termodinamika.)" },
    { q: "Seorang astronot di pesawat yang bergerak $0{,}6c$ mengukur selang waktu suatu kejadian $10$ s. Selang waktu yang diukur pengamat diam di Bumi adalah ...", options: ["$8$ s", "$12{,}5$ s", "$6$ s", "$16$ s"], answer: 1, solution: "Langkah 1: gunakan rumus dilatasi waktu $\\Delta t = \\gamma \\Delta t_0$ dengan $\\gamma = \\frac{1}{\\sqrt{1 - v^2/c^2}}$. Langkah 2: $v = 0{,}6c$, sehingga $\\gamma = \\frac{1}{\\sqrt{1 - 0{,}36}} = \\frac{1}{\\sqrt{0{,}64}} = \\frac{1}{0{,}8} = 1{,}25$. Langkah 3: $\\Delta t = 1{,}25 \\times 10 = 12{,}5$ s. Waktu terasa lebih lama bagi pengamat yang diam." },
    { q: "Sebuah roket yang panjangnya $100$ m saat diam bergerak dengan kecepatan $0{,}8c$ relatif terhadap pengamat di Bumi. Panjang roket menurut pengamat di Bumi adalah ...", options: ["$100$ m", "$60$ m", "$166{,}7$ m", "$80$ m"], answer: 1, solution: "Langkah 1: gunakan rumus kontraksi panjang $L = \\frac{L_0}{\\gamma}$. Langkah 2: $v = 0{,}8c$, sehingga $\\gamma = \\frac{1}{\\sqrt{1 - 0{,}64}} = \\frac{1}{0{,}6} = \\frac{5}{3}$. Langkah 3: $L = \\frac{100}{5/3} = 100 \\times \\frac{3}{5} = 60$ m. Benda yang bergerak tampak lebih pendek searah geraknya." },
    { q: "Salah satu postulat teori relativitas khusus Einstein menyatakan bahwa ...", options: ["kecepatan cahaya bergantung pada gerak sumbernya", "kecepatan cahaya sama di semua kerangka acuan inersia", "waktu bersifat mutlak bagi semua pengamat", "massa benda berkurang saat kecepatannya bertambah"], answer: 1, solution: "Langkah 1: Einstein mengajukan dua postulat relativitas khusus. Langkah 2: postulat pertama: hukum fisika sama di semua kerangka inersia; postulat kedua: kelajuan cahaya di ruang hampa ($c$) sama untuk semua pengamat, tidak bergantung pada gerak sumber maupun pengamat. Langkah 3: jadi jawabannya adalah kecepatan cahaya sama di semua kerangka acuan inersia. (Catatan: waktu justru relatif, bukan mutlak.)" },
    { q: "Cahaya berfrekuensi $6 \\times 10^{14}$ Hz menyinari permukaan logam ($h = 6{,}6 \\times 10^{-34}$ J s). Energi tiap foton cahaya tersebut adalah ...", options: ["$4 \\times 10^{-19}$ J", "$1{,}1 \\times 10^{-19}$ J", "$3{,}96 \\times 10^{-48}$ J", "$9{,}9 \\times 10^{-20}$ J"], answer: 0, solution: "Langkah 1: gunakan persamaan Planck $E = hf$. Langkah 2: $E = (6{,}6 \\times 10^{-34})(6 \\times 10^{14}) = 39{,}6 \\times 10^{-20}$. Langkah 3: $= 3{,}96 \\times 10^{-19}$ J $\\approx 4 \\times 10^{-19}$ J." },
    { q: "Dalam peristiwa efek fotolistrik, energi kinetik maksimum elektron yang terlepas dari logam bergantung pada ...", options: ["intensitas cahaya yang datang", "frekuensi cahaya yang datang", "luas permukaan logam", "suhu logam"], answer: 1, solution: "Langkah 1: menurut Einstein, energi foton $E = hf$ diserap seluruhnya oleh satu elektron. Langkah 2: energi kinetik maksimum $E_{k\\text{maks}} = hf - W_0$, dengan $W_0$ fungsi kerja logam. Langkah 3: jadi $E_{k\\text{maks}}$ bergantung pada frekuensi cahaya, bukan intensitasnya; intensitas hanya memengaruhi banyaknya elektron yang terlepas." },
    { q: "Menurut model atom Bohr, besar energi elektron pada kulit ke-$2$ atom hidrogen adalah ... ($E_n = -\\frac{13{,}6}{n^2}$ eV)", options: ["$-13{,}6$ eV", "$-3{,}4$ eV", "$-6{,}8$ eV", "$-1{,}51$ eV"], answer: 1, solution: "Langkah 1: gunakan $E_n = -\\frac{13{,}6}{n^2}$ eV dengan $n = 2$. Langkah 2: $E_2 = -\\frac{13{,}6}{2^2} = -\\frac{13{,}6}{4}$. Langkah 3: $= -3{,}4$ eV. Tanda negatif menunjukkan elektron terikat pada inti." },
    { q: "Elektron atom hidrogen berpindah dari kulit $n = 3$ ke $n = 2$. Energi foton yang dipancarkan adalah ...", options: ["$10{,}2$ eV", "$1{,}89$ eV", "$12{,}09$ eV", "$3{,}4$ eV"], answer: 1, solution: "Langkah 1: energi foton $= E_{\\text{awal}} - E_{\\text{akhir}} = 13{,}6\\left(\\frac{1}{n_{\\text{akhir}}^2} - \\frac{1}{n_{\\text{awal}}^2}\\right)$ eV. Langkah 2: $= 13{,}6\\left(\\frac{1}{4} - \\frac{1}{9}\\right) = 13{,}6 \\times \\frac{5}{36}$. Langkah 3: $= \\frac{68}{36} \\approx 1{,}89$ eV. Foton ini berada pada deret Balmer (cahaya tampak, merah)." },
    { q: "Sebuah elektron bergerak dengan kecepatan $10^6$ m/s ($m_e = 9{,}1 \\times 10^{-31}$ kg, $h = 6{,}63 \\times 10^{-34}$ J s). Panjang gelombang de Broglie elektron tersebut adalah ...", options: ["$7{,}3 \\times 10^{-10}$ m", "$6{,}6 \\times 10^{-34}$ m", "$9{,}1 \\times 10^{-25}$ m", "$1{,}37 \\times 10^{9}$ m"], answer: 0, solution: "Langkah 1: gunakan $\\lambda = \\frac{h}{p} = \\frac{h}{mv}$. Langkah 2: $p = (9{,}1 \\times 10^{-31})(10^6) = 9{,}1 \\times 10^{-25}$ kg m/s. Langkah 3: $\\lambda = \\frac{6{,}63 \\times 10^{-34}}{9{,}1 \\times 10^{-25}} \\approx 7{,}3 \\times 10^{-10}$ m, seorde dengan jarak antaratom." },
    { q: "Pernyataan yang tepat mengenai sifat cahaya adalah ...", options: ["cahaya hanya bersifat sebagai gelombang", "cahaya hanya bersifat sebagai partikel", "cahaya memiliki sifat dualisme gelombang-partikel", "cahaya tidak memiliki energi"], answer: 2, solution: "Langkah 1: gejala interferensi dan difraksi menunjukkan cahaya bersifat gelombang (Huygens). Langkah 2: gejala efek fotolistrik menunjukkan cahaya bersifat partikel/foton (Einstein). Langkah 3: kedua sifat ini tidak saling meniadakan, melainkan melengkapi: cahaya memiliki dualisme gelombang-partikel." },
    { q: "Menurut model atom Bohr, elektron dapat mengelilingi inti tanpa memancarkan energi karena ...", options: ["elektron bergerak dengan kecepatan tetap", "elektron berada pada lintasan stasioner dengan momentum sudut terkuantisasi", "inti atom tidak bermuatan", "gaya Coulomb pada elektron sama dengan nol"], answer: 1, solution: "Langkah 1: fisika klasik meramalkan elektron yang mengorbit akan memancarkan energi dan jatuh ke inti. Langkah 2: Bohr mempostulatkan elektron hanya boleh berada pada lintasan-lintasan stasioner tertentu dengan momentum sudut $mvr = n\\frac{h}{2\\pi}$. Langkah 3: selama di lintasan stasioner, elektron tidak memancarkan energi; energi hanya dipancarkan/diserap saat berpindah lintasan." },
{ q: "Dimensi dari besaran kecepatan adalah ...", options: ["$[M][L][T]^{-1}$", "$[L][T]^{-1}$", "$[L][T]^{-2}$", "$[M][L]^{2}[T]^{-1}$"], answer: 1, solution: "1. Diketahui kecepatan $v = \\frac{s}{t} = \\frac{\\text{jarak}}{\\text{waktu}}$. 2. Gunakan rumus dimensi: dimensi jarak $[L]$ dibagi dimensi waktu $[T]$ menghasilkan $[L][T]^{-1}$. 3. Jadi jawabannya $[L][T]^{-1}$." },
{ q: "Dimensi dari besaran gaya adalah ...", options: ["$[M][L][T]^{-2}$", "$[M][L]^{2}[T]^{-2}$", "$[M][L][T]^{-1}$", "$[L][T]^{-2}$"], answer: 0, solution: "1. Diketahui gaya $F = m \\times a$. 2. Gunakan rumus dimensi: massa $[M]$ dikali percepatan $[L][T]^{-2}$ menghasilkan $[M][L][T]^{-2}$. 3. Jadi jawabannya $[M][L][T]^{-2}$." },
{ q: "Dimensi dari besaran energi adalah ...", options: ["$[M][L]^{2}[T]^{-1}$", "$[M][L][T]^{-2}$", "$[M][L]^{2}[T]^{-2}$", "$[M]^{2}[L]^{2}[T]^{-2}$"], answer: 2, solution: "1. Diketahui energi $E = F \\times s$ (gaya kali perpindahan). 2. Gunakan rumus dimensi: $[M][L][T]^{-2} \\times [L] = [M][L]^{2}[T]^{-2}$. 3. Jadi jawabannya $[M][L]^{2}[T]^{-2}$." },
{ q: "Dimensi dari besaran daya adalah ...", options: ["$[M][L]^{2}[T]^{-2}$", "$[M][L][T]^{-3}$", "$[M][L]^{3}[T]^{-3}$", "$[M][L]^{2}[T]^{-3}$"], answer: 3, solution: "1. Diketahui daya $P = \\frac{W}{t} = \\frac{\\text{usaha}}{\\text{waktu}}$. 2. Gunakan rumus dimensi: $[M][L]^{2}[T]^{-2}$ dibagi $[T]$ menghasilkan $[M][L]^{2}[T]^{-3}$. 3. Jadi jawabannya $[M][L]^{2}[T]^{-3}$." },
{ q: "Dimensi dari besaran tekanan adalah ...", options: ["$[M][L]^{-1}[T]^{-2}$", "$[M][L][T]^{-2}$", "$[M][L]^{-2}[T]^{-2}$", "$[M][L]^{2}[T]^{-2}$"], answer: 0, solution: "1. Diketahui tekanan $p = \\frac{F}{A} = \\frac{\\text{gaya}}{\\text{luas}}$. 2. Gunakan rumus dimensi: $[M][L][T]^{-2}$ dibagi $[L]^{2}$ menghasilkan $[M][L]^{-1}[T]^{-2}$. 3. Jadi jawabannya $[M][L]^{-1}[T]^{-2}$." },
{ q: "Dimensi dari besaran momentum adalah ...", options: ["$[M][L]^{2}[T]^{-1}$", "$[M][L][T]^{-2}$", "$[M][L][T]^{-1}$", "$[M][T]^{-1}$"], answer: 2, solution: "1. Diketahui momentum $p = m \\times v$. 2. Gunakan rumus dimensi: massa $[M]$ dikali kecepatan $[L][T]^{-1}$ menghasilkan $[M][L][T]^{-1}$. 3. Jadi jawabannya $[M][L][T]^{-1}$." },
{ q: "Besaran yang memiliki dimensi $[M][L]^{2}[T]^{-2}$ adalah ...", options: ["gaya", "energi", "daya", "momentum"], answer: 1, solution: "1. Diketahui dimensi yang ditanyakan $[M][L]^{2}[T]^{-2}$. 2. Gunakan analisis dimensi: gaya berdimensi $[M][L][T]^{-2}$, daya $[M][L]^{2}[T]^{-3}$, momentum $[M][L][T]^{-1}$, sedangkan energi $= F \\times s$ berdimensi $[M][L]^{2}[T]^{-2}$. 3. Jadi jawabannya energi." },
{ q: "Pasangan besaran berikut yang berdimensi sama adalah ...", options: ["gaya dan tekanan", "daya dan gaya", "momentum dan energi", "usaha dan energi"], answer: 3, solution: "1. Diketahui usaha $W = F \\times s$ dan energi memiliki rumus dimensi yang sama. 2. Gunakan analisis dimensi: usaha dan energi keduanya berdimensi $[M][L]^{2}[T]^{-2}$, sedangkan pasangan lain dimensinya berbeda (misal daya $[M][L]^{2}[T]^{-3}$). 3. Jadi jawabannya usaha dan energi." },
{ q: "Satuan daya dalam Sistem Internasional (SI) adalah ...", options: ["joule", "watt", "newton", "volt"], answer: 1, solution: "1. Diketahui daya $P = \\frac{W}{t}$ dengan satuan $\\text{J/s}$. 2. Satuan $\\text{J/s}$ diberi nama watt (W). 3. Jadi jawabannya watt (joule untuk energi, newton untuk gaya, volt untuk tegangan listrik)." },
{ q: "Satu joule ($1$ J) setara dengan ...", options: ["$1\\ \\text{N/m}$", "$1\\ \\text{W/m}$", "$1\\ \\text{N}\\cdot\\text{m}$", "$1\\ \\text{kg/s}^{2}$"], answer: 2, solution: "1. Diketahui joule adalah satuan usaha/energi. 2. Gunakan rumus $W = F \\times s$ sehingga $1\\ \\text{J} = 1\\ \\text{N} \\times 1\\ \\text{m} = 1\\ \\text{N}\\cdot\\text{m}$. 3. Jadi jawabannya $1\\ \\text{N}\\cdot\\text{m}$." },
{ q: "Jumlah angka penting pada $0{,}00450$ adalah ...", options: ["3", "2", "5", "6"], answer: 0, solution: "1. Diketahui bilangan $0{,}00450$. 2. Gunakan aturan angka penting: angka nol di depan (sebelum angka bukan nol) tidak dihitung, sedangkan nol di belakang koma setelah angka bukan nol dihitung. Angka pentingnya adalah 4, 5, dan 0 terakhir. 3. Jadi jawabannya 3 angka penting." },
{ q: "Hasil pengukuran panjang $2{,}50$ cm dan $2{,}5$ cm. Pernyataan yang tepat adalah ...", options: ["keduanya sama teliti", "$2{,}50$ cm lebih teliti karena memiliki 3 angka penting", "$2{,}5$ cm lebih teliti", "keduanya tidak memiliki angka penting"], answer: 1, solution: "1. Diketahui $2{,}50$ cm memiliki 3 angka penting dan $2{,}5$ cm memiliki 2 angka penting. 2. Gunakan konsep ketelitian: semakin banyak angka penting, semakin teliti alat ukur yang digunakan. 3. Jadi jawabannya $2{,}50$ cm lebih teliti karena memiliki 3 angka penting." },
{ q: "Kelajuan $72$ km/jam setara dengan ...", options: ["$72\\ \\text{m/s}$", "$36\\ \\text{m/s}$", "$2\\ \\text{m/s}$", "$20\\ \\text{m/s}$"], answer: 3, solution: "1. Diketahui $72$ km/jam. 2. Gunakan konversi: $72 \\times \\frac{1000\\ \\text{m}}{3600\\ \\text{s}} = \\frac{72000}{3600}$. 3. Jadi jawabannya $20\\ \\text{m/s}$." },
{ q: "Jarak $2{,}5$ km setara dengan ...", options: ["2500 m", "250 m", "25 m", "25000 m"], answer: 0, solution: "1. Diketahui $2{,}5$ km. 2. Gunakan konversi $1$ km $= 1000$ m, sehingga $2{,}5 \\times 1000 = 2500$. 3. Jadi jawabannya 2500 m." },
{ q: "Volume $3$ cm$^{3}$ setara dengan ...", options: ["$3\\ \\times 10^{-2}\\ \\text{m}^{3}$", "$3\\ \\times 10^{-6}\\ \\text{m}^{3}$", "$3\\ \\times 10^{-4}\\ \\text{m}^{3}$", "$3000\\ \\text{m}^{3}$"], answer: 1, solution: "1. Diketahui $3$ cm$^{3}$ dan $1$ cm $= 10^{-2}$ m. 2. Gunakan konversi: $3 \\times (10^{-2})^{3}\\ \\text{m}^{3} = 3 \\times 10^{-6}\\ \\text{m}^{3}$. 3. Jadi jawabannya $3\\ \\times 10^{-6}\\ \\text{m}^{3}$." },
{ q: "Massa jenis $1{,}2$ g/cm$^{3}$ setara dengan ...", options: ["120 kg/m$^{3}$", "12 kg/m$^{3}$", "1200 kg/m$^{3}$", "1,2 kg/m$^{3}$"], answer: 2, solution: "1. Diketahui $1{,}2$ g/cm$^{3}$. 2. Gunakan konversi: $1$ g $= 10^{-3}$ kg dan $1$ cm$^{3} = 10^{-6}$ m$^{3}$, sehingga $1{,}2 \\times \\frac{10^{-3}}{10^{-6}} = 1{,}2 \\times 10^{3} = 1200$. 3. Jadi jawabannya 1200 kg/m$^{3}$." },
{ q: "Waktu $45$ menit setara dengan ...", options: ["2700 s", "4500 s", "450 s", "27 s"], answer: 0, solution: "1. Diketahui $45$ menit. 2. Gunakan konversi $1$ menit $= 60$ sekon, sehingga $45 \\times 60 = 2700$. 3. Jadi jawabannya 2700 s." },
{ q: "Volume $2$ liter setara dengan ...", options: ["0,2 m$^{3}$", "0,02 m$^{3}$", "2000 m$^{3}$", "0,002 m$^{3}$"], answer: 3, solution: "1. Diketahui $2$ liter. 2. Gunakan konversi $1$ liter $= 1$ dm$^{3} = 10^{-3}$ m$^{3}$, sehingga $2 \\times 10^{-3} = 0{,}002$. 3. Jadi jawabannya 0,002 m$^{3}$." },
{ q: "Hasil perkalian $2{,}50 \\times 4{,}0$ menurut aturan angka penting adalah ...", options: ["10,0", "10", "10,00", "1,0"], answer: 1, solution: "1. Diketahui $2{,}50 \\times 4{,}0 = 10{,}0$. 2. Gunakan aturan perkalian angka penting: hasil mengikuti jumlah angka penting paling sedikit, yaitu 2 angka penting (dari $4{,}0$). 3. Jadi jawabannya 10 (2 angka penting)." },
{ q: "Hasil penjumlahan $12{,}5 + 3{,}25$ menurut aturan angka penting adalah ...", options: ["15,75", "16", "15,8", "15,7"], answer: 2, solution: "1. Diketahui $12{,}5 + 3{,}25 = 15{,}75$. 2. Gunakan aturan penjumlahan angka penting: hasil mengikuti jumlah desimal paling sedikit, yaitu 1 desimal (dari $12{,}5$), sehingga $15{,}75$ dibulatkan menjadi $15{,}8$. 3. Jadi jawabannya 15,8." },
{ q: "Hasil pembagian $8{,}45 \\div 2{,}0$ menurut aturan angka penting adalah ...", options: ["4,2", "4,225", "4,23", "4"], answer: 0, solution: "1. Diketahui $8{,}45 \\div 2{,}0 = 4{,}225$. 2. Gunakan aturan pembagian angka penting: hasil mengikuti jumlah angka penting paling sedikit, yaitu 2 angka penting (dari $2{,}0$), sehingga $4{,}225$ dibulatkan menjadi $4{,}2$. 3. Jadi jawabannya 4,2." },
{ q: "Bilangan $0{,}00025$ dalam notasi ilmiah yang benar adalah ...", options: ["$2{,}5\\ \\times 10^{-5}$", "$25\\ \\times 10^{-4}$", "$0{,}25\\ \\times 10^{-3}$", "$2{,}5\\ \\times 10^{-4}$"], answer: 3, solution: "1. Diketahui bilangan $0{,}00025$. 2. Gunakan notasi ilmiah $a \\times 10^{n}$ dengan $1 \\le a < 10$: koma digeser 4 tempat ke kanan sehingga $n = -4$. 3. Jadi jawabannya $2{,}5\\ \\times 10^{-4}$." },
{ q: "Kelajuan $90$ km/jam setara dengan ...", options: ["$32{,}4\\ \\text{m/s}$", "$9\\ \\text{m/s}$", "$25\\ \\text{m/s}$", "$250\\ \\text{m/s}$"], answer: 2, solution: "1. Diketahui $90$ km/jam. 2. Gunakan konversi: $90 \\times \\frac{1000\\ \\text{m}}{3600\\ \\text{s}} = \\frac{90000}{3600} = 25$. 3. Jadi jawabannya $25\\ \\text{m/s}$." },
{ q: "Sebuah sepeda motor bergerak lurus beraturan menempuh jarak $120$ m dalam waktu $30$ s. Kelajuan motor tersebut adalah ...", options: ["$4\\ \\text{m/s}$", "$3{,}6\\ \\text{m/s}$", "$150\\ \\text{m/s}$", "$0{,}25\\ \\text{m/s}$"], answer: 0, solution: "1. Diketahui $s = 120\\ \\text{m}$ dan $t = 30\\ \\text{s}$. 2. Gunakan rumus GLB $v = \\frac{s}{t} = \\frac{120}{30}$. 3. Jadi jawabannya $4\\ \\text{m/s}$." },
{ q: "Sebuah kereta bergerak dengan kelajuan tetap $25$ m/s selama $2$ menit. Jarak yang ditempuh kereta adalah ...", options: ["50 m", "300 m", "3000 m", "145 m"], answer: 2, solution: "1. Diketahui $v = 25\\ \\text{m/s}$ dan $t = 2$ menit $= 120$ s. 2. Gunakan rumus GLB $s = v \\times t = 25 \\times 120$. 3. Jadi jawabannya 3000 m." },
{ q: "Sebuah benda bergerak dengan kecepatan awal $10$ m/s lalu dipercepat beraturan $3$ m/s$^{2}$ selama $5$ sekon. Kecepatan akhir benda adalah ...", options: ["15 m/s", "25 m/s", "18 m/s", "75 m/s"], answer: 1, solution: "1. Diketahui $v_0 = 10\\ \\text{m/s}$, $a = 3\\ \\text{m/s}^{2}$, $t = 5\\ \\text{s}$. 2. Gunakan rumus GLBB $v_t = v_0 + at = 10 + (3)(5)$. 3. Jadi jawabannya $25\\ \\text{m/s}$." },
{ q: "Sebuah bus melaju $30$ m/s lalu direm dengan perlambatan tetap $2$ m/s$^{2}$. Jarak yang ditempuh bus hingga berhenti adalah ...", options: ["450 m", "60 m", "15 m", "225 m"], answer: 3, solution: "1. Diketahui $v_0 = 30\\ \\text{m/s}$, $v_t = 0$, $a = -2\\ \\text{m/s}^{2}$. 2. Gunakan rumus $v_t^{2} = v_0^{2} + 2as$, sehingga $0 = 900 + 2(-2)s$ dan $4s = 900$. 3. Jadi jawabannya $225\\ \\text{m}$." },
{ q: "Sebuah benda mula-mula diam dipercepat beraturan $4$ m/s$^{2}$ hingga menempuh jarak $32$ m. Waktu yang diperlukan adalah ...", options: ["8 s", "4 s", "2 s", "16 s"], answer: 1, solution: "1. Diketahui $v_0 = 0$, $a = 4\\ \\text{m/s}^{2}$, $s = 32\\ \\text{m}$. 2. Gunakan rumus $s = v_0 t + \\frac{1}{2}at^{2}$, sehingga $32 = \\frac{1}{2}(4)t^{2} = 2t^{2}$ dan $t^{2} = 16$. 3. Jadi jawabannya $4\\ \\text{s}$." },
{ q: "Sebuah mobil bergerak dengan kecepatan awal $5$ m/s dan percepatan tetap $2$ m/s$^{2}$ selama $6$ sekon. Jarak yang ditempuh mobil adalah ...", options: ["66 m", "30 m", "36 m", "96 m"], answer: 0, solution: "1. Diketahui $v_0 = 5\\ \\text{m/s}$, $a = 2\\ \\text{m/s}^{2}$, $t = 6\\ \\text{s}$. 2. Gunakan rumus $s = v_0 t + \\frac{1}{2}at^{2} = (5)(6) + \\frac{1}{2}(2)(36) = 30 + 36$. 3. Jadi jawabannya $66\\ \\text{m}$." },
{ q: "Sebuah batu dijatuhkan dari ketinggian $45$ m ($g = 10$ m/s$^{2}$). Waktu yang dibutuhkan batu mencapai tanah adalah ...", options: ["9 s", "4,5 s", "3 s", "6 s"], answer: 2, solution: "1. Diketahui $h = 45\\ \\text{m}$, $v_0 = 0$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $h = \\frac{1}{2}gt^{2}$, sehingga $45 = 5t^{2}$ dan $t^{2} = 9$. 3. Jadi jawabannya $3\\ \\text{s}$." },
{ q: "Sebuah benda jatuh bebas selama $4$ sekon ($g = 10$ m/s$^{2}$). Ketinggian awal benda dari tanah adalah ...", options: ["40 m", "20 m", "160 m", "80 m"], answer: 3, solution: "1. Diketahui $t = 4\\ \\text{s}$, $v_0 = 0$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $h = \\frac{1}{2}gt^{2} = \\frac{1}{2}(10)(16)$. 3. Jadi jawabannya $80\\ \\text{m}$." },
{ q: "Sebuah bola dilempar vertikal ke atas dengan kecepatan awal $30$ m/s ($g = 10$ m/s$^{2}$). Waktu yang dibutuhkan untuk mencapai titik tertinggi adalah ...", options: ["6 s", "3 s", "30 s", "1,5 s"], answer: 1, solution: "1. Diketahui $v_0 = 30\\ \\text{m/s}$, di titik tertinggi $v_t = 0$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $v_t = v_0 - gt$, sehingga $0 = 30 - 10t$ dan $t = 3$. 3. Jadi jawabannya $3\\ \\text{s}$." },
{ q: "Dari tanah, sebuah bola dilempar vertikal ke atas dengan kecepatan awal $30$ m/s ($g = 10$ m/s$^{2}$). Ketinggian maksimum bola dari tanah adalah ...", options: ["45 m", "90 m", "30 m", "15 m"], answer: 0, solution: "1. Diketahui $v_0 = 30\\ \\text{m/s}$ dan $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $h_{\\text{maks}} = \\frac{v_0^{2}}{2g} = \\frac{900}{20}$. 3. Jadi jawabannya $45\\ \\text{m}$." },
{ q: "Sebuah benda dilempar vertikal ke atas dengan kecepatan awal $25$ m/s ($g = 10$ m/s$^{2}$). Kecepatan benda setelah $1$ sekon adalah ...", options: ["35 m/s", "25 m/s", "15 m/s", "10 m/s"], answer: 2, solution: "1. Diketahui $v_0 = 25\\ \\text{m/s}$, $t = 1\\ \\text{s}$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $v_t = v_0 - gt = 25 - (10)(1)$. 3. Jadi jawabannya $15\\ \\text{m/s}$." },
{ q: "Sebuah peluru ditembakkan dengan kecepatan awal $20$ m/s membentuk sudut $30^{\\circ}$ terhadap horizontal ($g = 10$ m/s$^{2}$). Ketinggian maksimum peluru adalah ...", options: ["20 m", "10 m", "2,5 m", "5 m"], answer: 3, solution: "1. Diketahui $v_0 = 20\\ \\text{m/s}$, $\\theta = 30^{\\circ}$ ($\\sin 30^{\\circ} = 0{,}5$), $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $h_{\\text{maks}} = \\frac{v_0^{2} \\sin^{2}\\theta}{2g} = \\frac{(400)(0{,}25)}{20}$. 3. Jadi jawabannya $5\\ \\text{m}$." },
{ q: "Sebuah peluru ditembakkan dengan kecepatan awal $40$ m/s membentuk sudut $30^{\\circ}$ terhadap horizontal ($g = 10$ m/s$^{2}$). Jarak mendatar maksimum (jangkauan) peluru adalah ...", options: ["$40\\sqrt{3}$ m", "$80\\sqrt{3}$ m", "$160\\sqrt{3}$ m", "$80$ m"], answer: 1, solution: "1. Diketahui $v_0 = 40\\ \\text{m/s}$, $\\theta = 30^{\\circ}$ ($\\sin 60^{\\circ} = \\frac{\\sqrt{3}}{2}$), $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $R = \\frac{v_0^{2} \\sin 2\\theta}{g} = \\frac{(1600)(\\sqrt{3}/2)}{10} = \\frac{800\\sqrt{3}}{10}$. 3. Jadi jawabannya $80\\sqrt{3}\\ \\text{m}$." },
{ q: "Sebuah bola ditendang dengan kecepatan awal $20$ m/s membentuk sudut $30^{\\circ}$ terhadap horizontal ($g = 10$ m/s$^{2}$). Lama bola melayang di udara adalah ...", options: ["2 s", "4 s", "1 s", "20 s"], answer: 0, solution: "1. Diketahui $v_0 = 20\\ \\text{m/s}$, $\\theta = 30^{\\circ}$ ($\\sin 30^{\\circ} = 0{,}5$), $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $t = \\frac{2v_0 \\sin\\theta}{g} = \\frac{2(20)(0{,}5)}{10} = \\frac{20}{10}$. 3. Jadi jawabannya $2\\ \\text{s}$." },
{ q: "Pada gerak parabola, besar kecepatan benda di titik tertinggi adalah ...", options: ["nol", "sama dengan $v_0$", "$v_0\\cos\\theta$ dengan arah horizontal", "maksimum"], answer: 2, solution: "1. Diketahui pada gerak parabola kecepatan vertikal di titik tertinggi nol ($v_y = 0$). 2. Komponen horizontal kecepatan selalu tetap sebesar $v_x = v_0 \\cos \\theta$, sehingga kecepatan di titik tertinggi tinggal komponen horizontalnya. 3. Jadi jawabannya $v_0\\cos\\theta$ dengan arah horizontal." },
{ q: "Sudut elevasi yang menghasilkan jangkauan terjauh pada gerak parabola (dengan kelajuan awal sama) adalah ...", options: ["$30^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$", "$45^{\\circ}$"], answer: 3, solution: "1. Diketahui rumus jangkauan $R = \\frac{v_0^{2} \\sin 2\\theta}{g}$. 2. $R$ maksimum ketika $\\sin 2\\theta = 1$, yaitu $2\\theta = 90^{\\circ}$. 3. Jadi jawabannya $\\theta = 45^{\\circ}$." },
{ q: "Sebuah benda bergerak melingkar beraturan dengan frekuensi $2$ Hz dan jari-jari lintasan $0{,}5$ m. Kelajuan linear benda adalah ...", options: ["$\\pi$ m/s", "$2\\pi$ m/s", "$4\\pi$ m/s", "$0{,}5\\pi$ m/s"], answer: 1, solution: "1. Diketahui $f = 2\\ \\text{Hz}$ dan $r = 0{,}5\\ \\text{m}$. 2. Gunakan rumus $v = 2\\pi r f = 2\\pi (0{,}5)(2)$. 3. Jadi jawabannya $2\\pi\\ \\text{m/s}$." },
{ q: "Sebuah roda berputar dengan periode $0{,}5$ s. Kecepatan sudut roda tersebut adalah ...", options: ["$4\\pi$ rad/s", "$\\pi$ rad/s", "$2\\pi$ rad/s", "$8\\pi$ rad/s"], answer: 0, solution: "1. Diketahui $T = 0{,}5\\ \\text{s}$. 2. Gunakan rumus $\\omega = \\frac{2\\pi}{T} = \\frac{2\\pi}{0{,}5}$. 3. Jadi jawabannya $4\\pi\\ \\text{rad/s}$." },
{ q: "Sebuah kipas berputar $120$ rpm. Kecepatan sudut kipas dalam rad/s adalah ...", options: ["$2\\pi$ rad/s", "$120\\pi$ rad/s", "$4\\pi$ rad/s", "$60$ rad/s"], answer: 2, solution: "1. Diketahui $120$ rpm $= \\frac{120}{60} = 2$ putaran per sekon. 2. Gunakan konversi $1$ putaran $= 2\\pi$ rad, sehingga $\\omega = 2 \\times 2\\pi = 4\\pi$. 3. Jadi jawabannya $4\\pi\\ \\text{rad/s}$." },
{ q: "Sebuah benda bergerak melingkar dengan kelajuan $5$ m/s pada lintasan berjari-jari $10$ m. Percepatan sentripetal benda adalah ...", options: ["5 m/s$^{2}$", "10 m/s$^{2}$", "1,25 m/s$^{2}$", "2,5 m/s$^{2}$"], answer: 3, solution: "1. Diketahui $v = 5\\ \\text{m/s}$ dan $r = 10\\ \\text{m}$. 2. Gunakan rumus $a_s = \\frac{v^{2}}{r} = \\frac{25}{10}$. 3. Jadi jawabannya $2{,}5\\ \\text{m/s}^{2}$." },
{ q: "Sebuah mobil menikung dengan kelajuan $10$ m/s pada tikungan berjari-jari $25$ m. Percepatan sentripetal mobil adalah ...", options: ["2,5 m/s$^{2}$", "40 m/s$^{2}$", "4 m/s$^{2}$", "250 m/s$^{2}$"], answer: 2, solution: "1. Diketahui $v = 10\\ \\text{m/s}$ dan $r = 25\\ \\text{m}$. 2. Gunakan rumus $a_s = \\frac{v^{2}}{r} = \\frac{100}{25}$. 3. Jadi jawabannya $4\\ \\text{m/s}^{2}$." },
{ q: "Grafik kecepatan terhadap waktu ($v$--$t$) untuk gerak lurus berubah beraturan (GLBB) dipercepat berbentuk ...", options: ["garis lurus miring ke atas", "garis lurus horizontal", "garis lengkung parabola", "garis lurus miring ke bawah"], answer: 0, solution: "1. Diketahui pada GLBB dipercepat kecepatan bertambah secara beraturan terhadap waktu ($v_t = v_0 + at$). 2. Persamaan $v_t = v_0 + at$ adalah fungsi linear dengan kemiringan positif $a$, sehingga grafiknya garis lurus miring ke atas. 3. Jadi jawabannya garis lurus miring ke atas." },
{ q: "Grafik jarak terhadap waktu ($s$--$t$) untuk gerak lurus beraturan (GLB) berbentuk ...", options: ["garis lengkung", "garis lurus miring", "garis lurus horizontal", "garis zigzag"], answer: 1, solution: "1. Diketahui pada GLB jarak bertambah berbanding lurus dengan waktu ($s = vt$). 2. Persamaan $s = vt$ adalah fungsi linear dengan kemiringan $v$ (tetap, tak nol), sehingga grafiknya garis lurus miring. 3. Jadi jawabannya garis lurus miring." },
{ q: "Sebuah batu dilempar vertikal ke atas. Di titik tertinggi, keadaan batu adalah ...", options: ["kecepatan dan percepatan nol", "kecepatan maksimum, percepatan nol", "keduanya maksimum", "kecepatan nol, percepatan tetap $g$ ke bawah"], answer: 3, solution: "1. Diketahui di titik tertinggi batu sesaat berhenti sehingga $v = 0$. 2. Percepatan gravitasi $g$ bekerja terus-menerus ke bawah selama batu di udara dan tidak pernah nol. 3. Jadi jawabannya kecepatan nol, percepatan tetap $g$ ke bawah." },
{ q: "Sebuah benda bermassa $4$ kg bergerak dengan percepatan $2{,}5$ m/s$^{2}$. Besar gaya yang bekerja pada benda adalah ...", options: ["6,5 N", "1,6 N", "10 N", "16 N"], answer: 2, solution: "1. Diketahui $m = 4\\ \\text{kg}$ dan $a = 2{,}5\\ \\text{m/s}^{2}$. 2. Gunakan Hukum II Newton $F = m \\times a = 4 \\times 2{,}5$. 3. Jadi jawabannya $10\\ \\text{N}$." },
{ q: "Dua gaya searah $30$ N dan $20$ N bekerja pada benda bermassa $10$ kg. Percepatan benda adalah ...", options: ["5 m/s$^{2}$", "2 m/s$^{2}$", "1 m/s$^{2}$", "10 m/s$^{2}$"], answer: 0, solution: "1. Diketahui $F_1 = 30\\ \\text{N}$, $F_2 = 20\\ \\text{N}$ searah, $m = 10\\ \\text{kg}$. 2. Gunakan Hukum II Newton: resultan $F = 30 + 20 = 50\\ \\text{N}$, lalu $a = \\frac{F}{m} = \\frac{50}{10}$. 3. Jadi jawabannya $5\\ \\text{m/s}^{2}$." },
{ q: "Sebuah benda bermassa $8$ kg ditarik gaya $60$ N ke kanan dan $20$ N ke kiri. Percepatan benda adalah ...", options: ["10 m/s$^{2}$", "7,5 m/s$^{2}$", "2,5 m/s$^{2}$", "5 m/s$^{2}$"], answer: 3, solution: "1. Diketahui $F_{\\text{kanan}} = 60\\ \\text{N}$, $F_{\\text{kiri}} = 20\\ \\text{N}$, $m = 8\\ \\text{kg}$. 2. Gunakan Hukum II Newton: resultan $F = 60 - 20 = 40\\ \\text{N}$, lalu $a = \\frac{40}{8}$. 3. Jadi jawabannya $5\\ \\text{m/s}^{2}$ ke kanan." },
{ q: "Sebuah balok menekan lantai dengan gaya normal $50$ N. Jika koefisien gesek statis $\\mu_s = 0{,}4$, gaya gesek statis maksimum balok adalah ...", options: ["200 N", "20 N", "2 N", "12,5 N"], answer: 1, solution: "1. Diketahui $N = 50\\ \\text{N}$ dan $\\mu_s = 0{,}4$. 2. Gunakan rumus $f_{s\\text{ maks}} = \\mu_s \\times N = 0{,}4 \\times 50$. 3. Jadi jawabannya $20\\ \\text{N}$." },
{ q: "Sebuah benda bermassa $5$ kg meluncur di atas lantai kasar dengan koefisien gesek kinetis $\\mu_k = 0{,}2$ ($g = 10$ m/s$^{2}$). Besar gaya gesek kinetisnya adalah ...", options: ["1 N", "25 N", "10 N", "100 N"], answer: 2, solution: "1. Diketahui $m = 5\\ \\text{kg}$, $\\mu_k = 0{,}2$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $f_k = \\mu_k \\times N = \\mu_k \\times mg = 0{,}2 \\times 5 \\times 10$. 3. Jadi jawabannya $10\\ \\text{N}$." },
{ q: "Sebuah peti ditarik dengan gaya $15$ N tetapi tidak bergerak. Jika gaya gesek statis maksimumnya $20$ N, besar gaya gesek yang bekerja pada peti adalah ...", options: ["15 N", "20 N", "5 N", "0 N"], answer: 0, solution: "1. Diketahui gaya tarik $15\\ \\text{N} < f_{s\\text{ maks}} = 20\\ \\text{N}$, sehingga peti tetap diam. 2. Pada benda diam berlaku Hukum I Newton: resultan gaya nol, sehingga gaya gesek statis sama besar dengan gaya tarik yang mengimbanginya. 3. Jadi jawabannya $15\\ \\text{N}$." },
{ q: "Sebuah benda bermassa $6$ kg diam di atas lantai datar ($g = 10$ m/s$^{2}$). Besar gaya normal yang bekerja pada benda adalah ...", options: ["6 N", "0,6 N", "66 N", "60 N"], answer: 3, solution: "1. Diketahui $m = 6\\ \\text{kg}$ dan benda diam di lantai datar. 2. Gunakan kesetimbangan arah vertikal $N - mg = 0$, sehingga $N = mg = 6 \\times 10$. 3. Jadi jawabannya $60\\ \\text{N}$." },
{ q: "Sebuah balok bermassa $4$ kg diam pada bidang miring $30^{\\circ}$ ($g = 10$ m/s$^{2}$). Besar gaya normal pada balok adalah ...", options: ["20 N", "$20\\sqrt{3}$ N", "40 N", "$40\\sqrt{3}$ N"], answer: 1, solution: "1. Diketahui $m = 4\\ \\text{kg}$, $\\theta = 30^{\\circ}$ ($\\cos 30^{\\circ} = \\frac{\\sqrt{3}}{2}$), $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $N = mg \\cos\\theta = 4 \\times 10 \\times \\frac{\\sqrt{3}}{2} = 40 \\times \\frac{\\sqrt{3}}{2}$. 3. Jadi jawabannya $20\\sqrt{3}\\ \\text{N}$." },
{ q: "Seseorang bermassa $60$ kg berada di dalam lift yang dipercepat ke atas $2$ m/s$^{2}$ ($g = 10$ m/s$^{2}$). Gaya normal lantai lift pada orang tersebut adalah ...", options: ["600 N", "480 N", "720 N", "120 N"], answer: 2, solution: "1. Diketahui $m = 60\\ \\text{kg}$, $a = 2\\ \\text{m/s}^{2}$ ke atas. 2. Gunakan Hukum II Newton arah vertikal $N - mg = ma$, sehingga $N = m(g + a) = 60(10 + 2)$. 3. Jadi jawabannya $720\\ \\text{N}$." },
{ q: "Seseorang bermassa $60$ kg menaiki lift yang bergerak dipercepat ke bawah sebesar $2$ m/s$^{2}$ ($g = 10$ m/s$^{2}$). Besar gaya normal lantai lift terhadap orang itu adalah ...", options: ["480 N", "600 N", "720 N", "120 N"], answer: 0, solution: "1. Diketahui $m = 60\\ \\text{kg}$, $a = 2\\ \\text{m/s}^{2}$ ke bawah. 2. Gunakan Hukum II Newton arah vertikal $mg - N = ma$, sehingga $N = m(g - a) = 60(10 - 2)$. 3. Jadi jawabannya $480\\ \\text{N}$." },
{ q: "Sebuah benda bermassa $7$ kg digantung diam pada seutas tali ($g = 10$ m/s$^{2}$). Besar tegangan tali adalah ...", options: ["7 N", "73 N", "0,7 N", "70 N"], answer: 3, solution: "1. Diketahui $m = 7\\ \\text{kg}$ dan benda diam (setimbang). 2. Gunakan kesetimbangan $T - mg = 0$, sehingga $T = mg = 7 \\times 10$. 3. Jadi jawabannya $70\\ \\text{N}$." },
{ q: "Sebuah benda bermassa $5$ kg ditarik vertikal ke atas dengan percepatan $2$ m/s$^{2}$ ($g = 10$ m/s$^{2}$). Besar tegangan tali penariknya adalah ...", options: ["50 N", "60 N", "40 N", "10 N"], answer: 1, solution: "1. Diketahui $m = 5\\ \\text{kg}$, $a = 2\\ \\text{m/s}^{2}$ ke atas. 2. Gunakan Hukum II Newton $T - mg = ma$, sehingga $T = m(g + a) = 5(10 + 2)$. 3. Jadi jawabannya $60\\ \\text{N}$." },
{ q: "Dua benda bermassa $6$ kg dan $4$ kg dihubungkan tali melalui katrol licin ($g = 10$ m/s$^{2}$). Percepatan sistem kedua benda adalah ...", options: ["6 m/s$^{2}$", "10 m/s$^{2}$", "2 m/s$^{2}$", "0,2 m/s$^{2}$"], answer: 2, solution: "1. Diketahui $m_1 = 6\\ \\text{kg}$ dan $m_2 = 4\\ \\text{kg}$. 2. Gunakan rumus $a = \\frac{(m_1 - m_2)g}{m_1 + m_2} = \\frac{(6 - 4) \\times 10}{6 + 4} = \\frac{20}{10}$. 3. Jadi jawabannya $2\\ \\text{m/s}^{2}$." },
{ q: "Melalui sebuah katrol licin, dua benda bermassa $6$ kg dan $4$ kg dihubungkan dengan seutas tali ($g = 10$ m/s$^{2}$). Besar tegangan tali penghubungnya adalah ...", options: ["48 N", "60 N", "40 N", "24 N"], answer: 0, solution: "1. Diketahui dari perhitungan sebelumnya $a = 2\\ \\text{m/s}^{2}$. 2. Gunakan Hukum II Newton pada benda $6$ kg yang turun: $m_1 g - T = m_1 a$, sehingga $T = 60 - (6)(2) = 60 - 12$. 3. Jadi jawabannya $48\\ \\text{N}$." },
{ q: "Sebuah balok bermassa $5$ kg berada pada bidang miring $30^{\\circ}$ ($g = 10$ m/s$^{2}$). Besar komponen gaya berat yang sejajar bidang miring adalah ...", options: ["50 N", "$25\\sqrt{3}$ N", "5 N", "25 N"], answer: 3, solution: "1. Diketahui $m = 5\\ \\text{kg}$, $\\theta = 30^{\\circ}$ ($\\sin 30^{\\circ} = 0{,}5$), $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus komponen sejajar bidang $w_{\\text{sejajar}} = mg \\sin\\theta = 5 \\times 10 \\times 0{,}5$. 3. Jadi jawabannya $25\\ \\text{N}$." },
{ q: "Sebuah mobil bermassa $1000$ kg menikung dengan kelajuan $20$ m/s pada tikungan berjari-jari $100$ m. Besar gaya sentripetal yang dibutuhkan adalah ...", options: ["2000 N", "4000 N", "20000 N", "400 N"], answer: 1, solution: "1. Diketahui $m = 1000\\ \\text{kg}$, $v = 20\\ \\text{m/s}$, $r = 100\\ \\text{m}$. 2. Gunakan rumus $F_s = \\frac{mv^{2}}{r} = \\frac{(1000)(400)}{100}$. 3. Jadi jawabannya $4000\\ \\text{N}$." },
{ q: "Sebuah benda bermassa $0{,}5$ kg diikat tali lalu diputar horizontal dengan kelajuan $4$ m/s pada lintasan berjari-jari $2$ m. Besar tegangan tali (gaya sentripetal) adalah ...", options: ["8 N", "2 N", "4 N", "16 N"], answer: 2, solution: "1. Diketahui $m = 0{,}5\\ \\text{kg}$, $v = 4\\ \\text{m/s}$, $r = 2\\ \\text{m}$. 2. Gunakan rumus $F_s = \\frac{mv^{2}}{r} = \\frac{(0{,}5)(16)}{2} = \\frac{8}{2}$. 3. Jadi jawabannya $4\\ \\text{N}$." },
{ q: "Dua balok $4$ kg dan $8$ kg dihubungkan tali di atas lantai licin, lalu sistem ditarik gaya $24$ N. Besar tegangan tali di antara kedua balok adalah ...", options: ["16 N", "24 N", "8 N", "12 N"], answer: 0, solution: "1. Diketahui $m_1 = 4\\ \\text{kg}$, $m_2 = 8\\ \\text{kg}$, $F = 24\\ \\text{N}$. 2. Gunakan Hukum II Newton: percepatan sistem $a = \\frac{F}{m_1 + m_2} = \\frac{24}{12} = 2\\ \\text{m/s}^{2}$, lalu tegangan tali menarik balok $8$ kg sebesar $T = m_2 a = 8 \\times 2$. 3. Jadi jawabannya $16\\ \\text{N}$." },
{ q: "Saat bus yang melaju direm mendadak, penumpang terdorong ke depan. Peristiwa ini menunjukkan berlakunya ...", options: ["Hukum II Newton", "Hukum III Newton", "Hukum Hooke", "Hukum I Newton"], answer: 3, solution: "1. Diketahui penumpang cenderung mempertahankan gerak majunya saat bus berhenti. 2. Sifat benda mempertahankan keadaan geraknya (kelembaman/inersia) adalah isi Hukum I Newton. 3. Jadi jawabannya Hukum I Newton." },
{ q: "Roket dapat meluncur ke atas karena gas hasil pembakaran disemburkan ke bawah dengan kuat. Prinsip ini merupakan contoh ...", options: ["Hukum I Newton", "Hukum III Newton", "Hukum II Newton", "Hukum kekekalan energi"], answer: 1, solution: "1. Diketahui ada dua gaya berpasangan: gas didorong ke bawah (aksi) dan roket terdorong ke atas (reaksi). 2. Hukum III Newton menyatakan setiap aksi menimbulkan reaksi yang sama besar dan berlawanan arah. 3. Jadi jawabannya Hukum III Newton." },
{ q: "Arah gaya gesek yang bekerja pada benda yang meluncur adalah ...", options: ["searah gerak benda", "searah gaya berat", "berlawanan dengan arah gerak benda", "tegak lurus bidang sentuh"], answer: 2, solution: "1. Diketahui gaya gesek muncul pada bidang sentuh dua benda yang bergesekan. 2. Arah gaya gesek selalu berlawanan dengan arah gerak benda atau kecenderungan arah geraknya. 3. Jadi jawabannya berlawanan dengan arah gerak benda." },
{ q: "Gaya berat buku dan gaya normal meja pada buku yang diam di atas meja bukan pasangan aksi-reaksi karena ...", options: ["keduanya bekerja pada benda yang sama (buku)", "besar keduanya berbeda", "arah keduanya sama", "keduanya hanya ada saat benda bergerak"], answer: 0, solution: "1. Diketahui syarat pasangan aksi-reaksi Newton III: bekerja pada dua benda yang berbeda. 2. Gaya berat dan gaya normal sama-sama bekerja pada buku (satu benda), sehingga keduanya hanya saling mengimbangi menurut Hukum I Newton. 3. Jadi jawabannya keduanya bekerja pada benda yang sama (buku)." },
{ q: "Arah gaya sentripetal pada benda yang bergerak melingkar beraturan adalah ...", options: ["menjauhi pusat lingkaran", "searah kecepatan", "tegak lurus bidang putar", "menuju pusat lingkaran"], answer: 3, solution: "1. Diketahui gaya sentripetal $F_s = \\frac{mv^{2}}{r}$ mengubah arah kecepatan benda agar tetap melingkar. 2. Agar benda tidak terlempar keluar lintasan, gaya ini harus menarik benda ke pusat lingkaran. 3. Jadi jawabannya menuju pusat lingkaran." },
{ q: "Dua balok bermassa berbeda meluncur bebas pada bidang miring licin yang sama. Percepatan kedua balok adalah ...", options: ["balok yang berat lebih cepat", "sama, karena $a = g\\sin\\theta$ tidak bergantung massa", "balok yang ringan lebih cepat", "nol karena bidangnya licin"], answer: 1, solution: "1. Diketahui pada bidang miring licin resultan gaya sejajar bidang $= mg \\sin \\theta$. 2. Gunakan Hukum II Newton $a = \\frac{F}{m} = \\frac{mg \\sin \\theta}{m} = g \\sin \\theta$; massa saling meniadakan. 3. Jadi jawabannya sama, karena $a = g\\sin\\theta$ tidak bergantung massa." },
{ q: "Sebuah gaya $50$ N bekerja pada benda membentuk sudut $60^{\\circ}$ terhadap arah perpindahan sejauh $10$ m. Besar usaha gaya tersebut adalah ...", options: ["500 J", "433 J", "250 J", "25 J"], answer: 2, solution: "1. Diketahui $F = 50\\ \\text{N}$, $s = 10\\ \\text{m}$, $\\theta = 60^{\\circ}$ ($\\cos 60^{\\circ} = 0{,}5$). 2. Gunakan rumus $W = F \\times s \\times \\cos\\theta = 50 \\times 10 \\times 0{,}5$. 3. Jadi jawabannya $250\\ \\text{J}$." },
{ q: "Sebuah gaya $40$ N mendorong gerobak searah perpindahannya sejauh $15$ m. Besar usaha yang dilakukan gaya tersebut adalah ...", options: ["600 J", "55 J", "375 J", "2,67 J"], answer: 0, solution: "1. Diketahui $F = 40\\ \\text{N}$ searah perpindahan dan $s = 15\\ \\text{m}$. 2. Gunakan rumus $W = F \\times s = 40 \\times 15$. 3. Jadi jawabannya $600\\ \\text{J}$." },
{ q: "Sebuah benda bermassa $3$ kg bergerak dengan kecepatan $20$ m/s. Energi kinetik benda tersebut adalah ...", options: ["300 J", "1200 J", "60 J", "600 J"], answer: 3, solution: "1. Diketahui $m = 3\\ \\text{kg}$ dan $v = 20\\ \\text{m/s}$. 2. Gunakan rumus $E_k = \\frac{1}{2}mv^{2} = \\frac{1}{2}(3)(400)$. 3. Jadi jawabannya $600\\ \\text{J}$." },
{ q: "Sebuah peluru bermassa $0{,}5$ kg melesat dengan kecepatan $10$ m/s. Energi kinetik peluru adalah ...", options: ["50 J", "25 J", "5 J", "100 J"], answer: 1, solution: "1. Diketahui $m = 0{,}5\\ \\text{kg}$ dan $v = 10\\ \\text{m/s}$. 2. Gunakan rumus $E_k = \\frac{1}{2}mv^{2} = \\frac{1}{2}(0{,}5)(100)$. 3. Jadi jawabannya $25\\ \\text{J}$." },
{ q: "Sebuah benda bermassa $2$ kg berada pada ketinggian $15$ m dari tanah ($g = 10$ m/s$^{2}$). Energi potensial benda adalah ...", options: ["150 J", "30 J", "300 J", "17 J"], answer: 2, solution: "1. Diketahui $m = 2\\ \\text{kg}$, $h = 15\\ \\text{m}$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan rumus $E_p = mgh = 2 \\times 10 \\times 15$. 3. Jadi jawabannya $300\\ \\text{J}$." },
{ q: "Sebuah benda memiliki energi kinetik $150$ J dan energi potensial $250$ J. Energi mekanik benda tersebut adalah ...", options: ["400 J", "100 J", "37500 J", "1,67 J"], answer: 0, solution: "1. Diketahui $E_k = 150\\ \\text{J}$ dan $E_p = 250\\ \\text{J}$. 2. Gunakan rumus $E_m = E_k + E_p = 150 + 250$. 3. Jadi jawabannya $400\\ \\text{J}$." },
{ q: "Sebuah benda bermassa $4$ kg dijatuhkan dari ketinggian $20$ m ($g = 10$ m/s$^{2}$). Kecepatan benda saat tepat menyentuh tanah adalah ...", options: ["10 m/s", "$10\\sqrt{2}$ m/s", "40 m/s", "20 m/s"], answer: 3, solution: "1. Diketahui $m = 4\\ \\text{kg}$, $h = 20\\ \\text{m}$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan kekekalan energi mekanik $mgh = \\frac{1}{2}mv^{2}$, sehingga $v = \\sqrt{2gh} = \\sqrt{2 \\times 10 \\times 20} = \\sqrt{400}$. 3. Jadi jawabannya $20\\ \\text{m/s}$." },
{ q: "Sebuah benda bermassa $3$ kg dijatuhkan dari ketinggian $12$ m ($g = 10$ m/s$^{2}$). Saat benda berada pada ketinggian $5$ m, energi kinetiknya adalah ...", options: ["150 J", "210 J", "360 J", "60 J"], answer: 1, solution: "1. Diketahui $m = 3\\ \\text{kg}$, $h_{\\text{awal}} = 12\\ \\text{m}$, $h = 5\\ \\text{m}$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan kekekalan energi: $E_m = mgh_{\\text{awal}} = 3 \\times 10 \\times 12 = 360\\ \\text{J}$; $E_p = mgh = 3 \\times 10 \\times 5 = 150\\ \\text{J}$, sehingga $E_k = E_m - E_p = 360 - 150$. 3. Jadi jawabannya $210\\ \\text{J}$." },
{ q: "Sebuah bandul bermassa $0{,}5$ kg diayunkan dari ketinggian $0{,}8$ m di atas titik terendahnya ($g = 10$ m/s$^{2}$). Kelajuan bandul di titik terendah adalah ...", options: ["8 m/s", "16 m/s", "4 m/s", "2 m/s"], answer: 2, solution: "1. Diketahui $m = 0{,}5\\ \\text{kg}$, $h = 0{,}8\\ \\text{m}$, $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan kekekalan energi $mgh = \\frac{1}{2}mv^{2}$, sehingga $v = \\sqrt{2gh} = \\sqrt{2 \\times 10 \\times 0{,}8} = \\sqrt{16}$. 3. Jadi jawabannya $4\\ \\text{m/s}$." },
{ q: "Sebuah balok meluncur tanpa gesekan dari puncak bidang miring licin setinggi $5$ m ($g = 10$ m/s$^{2}$). Kelajuan balok di dasar bidang adalah ...", options: ["10 m/s", "5 m/s", "$5\\sqrt{2}$ m/s", "25 m/s"], answer: 0, solution: "1. Diketahui $h = 5\\ \\text{m}$ dan $g = 10\\ \\text{m/s}^{2}$. 2. Gunakan kekekalan energi $mgh = \\frac{1}{2}mv^{2}$, sehingga $v = \\sqrt{2gh} = \\sqrt{2 \\times 10 \\times 5} = \\sqrt{100}$. 3. Jadi jawabannya $10\\ \\text{m/s}$." },
{ q: "Sebuah mesin melakukan usaha $1200$ J dalam waktu $2$ menit. Daya mesin tersebut adalah ...", options: ["2400 W", "600 W", "20 W", "10 W"], answer: 3, solution: "1. Diketahui $W = 1200\\ \\text{J}$ dan $t = 2$ menit $= 120$ s. 2. Gunakan rumus $P = \\frac{W}{t} = \\frac{1200}{120}$. 3. Jadi jawabannya $10\\ \\text{W}$." },
{ q: "Sebuah gaya $200$ N mendorong benda sehingga bergerak dengan kelajuan tetap $15$ m/s searah gaya. Daya yang dihasilkan gaya tersebut adalah ...", options: ["13,3 W", "3000 W", "215 W", "300 W"], answer: 1, solution: "1. Diketahui $F = 200\\ \\text{N}$ dan $v = 15\\ \\text{m/s}$. 2. Gunakan rumus $P = F \\times v = 200 \\times 15$. 3. Jadi jawabannya $3000\\ \\text{W}$." },
{ q: "Sebuah pompa air berdaya $500$ W bekerja selama $10$ sekon. Besar usaha yang dilakukan pompa adalah ...", options: ["50 J", "500 J", "5000 J", "510 J"], answer: 2, solution: "1. Diketahui $P = 500\\ \\text{W}$ dan $t = 10\\ \\text{s}$. 2. Gunakan rumus $W = P \\times t = 500 \\times 10$. 3. Jadi jawabannya $5000\\ \\text{J}$." },
{ q: "Sebuah pegas dengan konstanta $200$ N/m diregangkan sejauh $0{,}1$ m. Energi potensial pegas tersebut adalah ...", options: ["1 J", "20 J", "2 J", "0,1 J"], answer: 0, solution: "1. Diketahui $k = 200\\ \\text{N/m}$ dan $x = 0{,}1\\ \\text{m}$. 2. Gunakan rumus $E_p = \\frac{1}{2}kx^{2} = \\frac{1}{2}(200)(0{,}1)^{2} = \\frac{1}{2}(200)(0{,}01)$. 3. Jadi jawabannya $1\\ \\text{J}$." },
{ q: "Sebuah benda bermassa $2$ kg kecepatannya berubah dari $4$ m/s menjadi $10$ m/s karena usaha gaya resultan. Besar usaha gaya resultan tersebut adalah ...", options: ["42 J", "116 J", "168 J", "84 J"], answer: 3, solution: "1. Diketahui $m = 2\\ \\text{kg}$, $v_1 = 4\\ \\text{m/s}$, $v_2 = 10\\ \\text{m/s}$. 2. Gunakan teorema usaha-energi $W = \\Delta E_k = \\frac{1}{2}m(v_2^{2} - v_1^{2}) = \\frac{1}{2}(2)(100 - 16) = 84$. 3. Jadi jawabannya $84\\ \\text{J}$." },
{ q: "Tanda usaha yang dilakukan gaya gesek pada benda yang meluncur adalah ...", options: ["positif", "negatif", "nol", "tak terdefinisi"], answer: 1, solution: "1. Diketahui arah gaya gesek selalu berlawanan dengan arah perpindahan benda. 2. Usaha $W = F \\times s \\times \\cos\\theta$ dengan $\\theta = 180^{\\circ}$ menghasilkan $\\cos 180^{\\circ} = -1$. 3. Jadi jawabannya negatif." },
{ q: "Usaha yang dilakukan suatu gaya bernilai nol jika ...", options: ["gaya searah perpindahan", "gaya berlawanan arah perpindahan", "gaya tegak lurus arah perpindahan", "gaya yang bekerja sangat besar"], answer: 2, solution: "1. Diketahui rumus usaha $W = F \\times s \\times \\cos\\theta$. 2. Jika gaya tegak lurus perpindahan maka $\\theta = 90^{\\circ}$ dan $\\cos 90^{\\circ} = 0$, sehingga $W = 0$. 3. Jadi jawabannya gaya tegak lurus arah perpindahan." },
{ q: "Kelajuan sebuah benda dijadikan dua kali semula. Energi kinetiknya menjadi ...", options: ["4 kali semula", "2 kali semula", "8 kali semula", "tetap"], answer: 0, solution: "1. Diketahui $E_k = \\frac{1}{2}mv^{2}$, energi kinetik sebanding dengan kuadrat kelajuan. 2. Jika $v' = 2v$, maka $E_k' = \\frac{1}{2}m(2v)^{2} = 4 \\times \\frac{1}{2}mv^{2} = 4E_k$. 3. Jadi jawabannya 4 kali semula." },
{ q: "Ketinggian sebuah benda dijadikan tiga kali semula. Energi potensial gravitasinya menjadi ...", options: ["9 kali semula", "1/3 kali semula", "tetap", "3 kali semula"], answer: 3, solution: "1. Diketahui $E_p = mgh$, energi potensial sebanding lurus dengan ketinggian. 2. Jika $h' = 3h$, maka $E_p' = mg(3h) = 3mgh = 3E_p$. 3. Jadi jawabannya 3 kali semula." },
{ q: "Energi mekanik suatu sistem bersifat kekal jika ...", options: ["selalu kekal dalam semua kondisi", "kekal jika tidak ada gaya gesek maupun usaha gaya luar", "kekal hanya untuk benda diam", "tidak pernah kekal"], answer: 1, solution: "1. Diketahui $E_m = E_k + E_p$. 2. Gaya gesek mengubah energi mekanik menjadi kalor dan usaha gaya luar mengubah total energi sistem, sehingga kekekalan $E_m$ hanya berlaku tanpa keduanya. 3. Jadi jawabannya kekal jika tidak ada gaya gesek maupun usaha gaya luar." },
{ q: "Tanda usaha yang dilakukan gaya berat pada benda yang jatuh bebas adalah ...", options: ["negatif", "nol", "positif", "tidak ada usaha"], answer: 2, solution: "1. Diketahui pada benda jatuh bebas arah gaya berat searah dengan arah perpindahan (ke bawah). 2. Usaha $W = F \\times s \\times \\cos\\theta$ dengan $\\theta = 0^{\\circ}$ menghasilkan $\\cos 0^{\\circ} = +1$. 3. Jadi jawabannya positif." },
{ q: "Dua mesin melakukan usaha yang sama besar. Mesin A berdaya dua kali mesin B. Waktu yang dibutuhkan mesin A adalah ...", options: ["setengah kali waktu mesin B", "dua kali waktu mesin B", "sama dengan waktu mesin B", "empat kali waktu mesin B"], answer: 0, solution: "1. Diketahui $W_A = W_B = W$ dan $P_A = 2P_B$. 2. Gunakan rumus $t = \\frac{W}{P}$: $t_A = \\frac{W}{2P_B} = \\frac{1}{2} \\times \\frac{W}{P_B} = \\frac{1}{2}t_B$. 3. Jadi jawabannya setengah kali waktu mesin B." },
{ q: "Energi kinetik sebuah benda yang sedang diam adalah ...", options: ["maksimum", "sama dengan energi potensialnya", "tak hingga", "nol"], answer: 3, solution: "1. Diketahui benda diam artinya $v = 0$. 2. Gunakan rumus $E_k = \\frac{1}{2}mv^{2} = \\frac{1}{2}m(0)^{2} = 0$. 3. Jadi jawabannya nol." },
{ q: "Dua benda bermassa sama, kelajuan benda A dua kali kelajuan benda B. Perbandingan energi kinetik A terhadap B adalah ...", options: ["sama besar", "4 kali", "2 kali", "8 kali"], answer: 1, solution: "1. Diketahui $m_A = m_B$ dan $v_A = 2v_B$. 2. Gunakan perbandingan $\\frac{E_{kA}}{E_{kB}} = \\frac{\\frac{1}{2}m_A v_A^{2}}{\\frac{1}{2}m_B v_B^{2}} = \\frac{(2v_B)^{2}}{v_B^{2}} = 4$. 3. Jadi jawabannya 4 kali." },
{ q: "Benda bermassa $2\\ \\text{kg}$ bergerak dengan kecepatan $6\\ \\text{m/s}$ menumbuk benda bermassa $3\\ \\text{kg}$ yang diam. Setelah tumbukan keduanya menyatu dan bergerak bersama. Kecepatan kedua benda setelah tumbukan adalah ...", options: ["6 m/s", "2,4 m/s", "3,6 m/s", "1,2 m/s"], answer: 1, solution: "1. Diketahui $m_1 = 2\\ \\text{kg}$, $v_1 = 6\\ \\text{m/s}$, $m_2 = 3\\ \\text{kg}$, $v_2 = 0$; tumbukan tak lenting sama sekali. 2. Gunakan kekekalan momentum $m_1 v_1 = (m_1 + m_2) v'$, sehingga $v' = \\frac{2 \\times 6}{2 + 3} = \\frac{12}{5} = 2{,}4\\ \\text{m/s}$. 3. Jadi jawabannya 2,4 m/s." },
{ q: "Sebuah bola dijatuhkan dari ketinggian $4\\ \\text{m}$ dan memantul kembali hingga ketinggian $1\\ \\text{m}$. Koefisien restitusi tumbukan bola dengan lantai adalah ...", options: ["0,25", "1", "0,5", "2"], answer: 2, solution: "1. Diketahui $h_1 = 4\\ \\text{m}$ dan $h_2 = 1\\ \\text{m}$. 2. Gunakan rumus koefisien restitusi dari pantulan $e = \\sqrt{\\frac{h_2}{h_1}} = \\sqrt{\\frac{1}{4}} = 0{,}5$. 3. Jadi jawabannya 0,5." },
{ q: "Benda A bermassa $1\\ \\text{kg}$ bergerak $4\\ \\text{m/s}$ menumbuk benda B bermassa $2\\ \\text{kg}$ yang bergerak $2\\ \\text{m/s}$ berlawanan arah. Jika tumbukannya lenting sempurna, kecepatan benda A setelah tumbukan adalah ...", options: ["4 m/s searah semula", "2 m/s", "0 m/s", "4 m/s berlawanan arah semula"], answer: 3, solution: "1. Diketahui $m_1 = 1\\ \\text{kg}$, $v_1 = 4\\ \\text{m/s}$, $m_2 = 2\\ \\text{kg}$, $v_2 = -2\\ \\text{m/s}$. 2. Gunakan rumus tumbukan lenting sempurna $v_1' = \\frac{(m_1 - m_2)v_1 + 2m_2 v_2}{m_1 + m_2} = \\frac{(1-2)(4) + 2(2)(-2)}{3} = \\frac{-12}{3} = -4\\ \\text{m/s}$. 3. Jadi jawabannya 4 m/s berlawanan arah semula." },
{ q: "Pada tumbukan tak lenting sama sekali, besaran yang tetap kekal adalah ...", options: ["momentum dan energi kinetik", "energi kinetik saja", "tidak ada yang kekal", "momentum saja"], answer: 3, solution: "1. Pada tumbukan tak lenting sama sekali kedua benda menyatu setelah tumbukan. 2. Sebagian energi kinetik berubah menjadi energi lain (bunyi, panas, deformasi) sehingga energi kinetik tidak kekal, tetapi tidak ada gaya luar impulsif sehingga momentum total sistem tetap kekal. 3. Jadi jawabannya momentum saja." },
{ q: "Bola bermassa $0{,}5\\ \\text{kg}$ datang dengan kecepatan $10\\ \\text{m/s}$, memantul balik dengan kecepatan $8\\ \\text{m/s}$. Besar impuls yang dialami bola adalah ...", options: ["9 N s", "1 N s", "5 N s", "18 N s"], answer: 0, solution: "1. Diketahui $m = 0{,}5\\ \\text{kg}$, $v_1 = 10\\ \\text{m/s}$, $v_2 = -8\\ \\text{m/s}$ (berbalik arah). 2. Gunakan $I = \\Delta p = m(v_2 - v_1) = 0{,}5 \\times (-8 - 10) = -9\\ \\text{N s}$. 3. Jadi besar impulsnya 9 N s." },
{ q: "Benda A ($3\\ \\text{kg}$, $4\\ \\text{m/s}$) menumbuk benda B ($2\\ \\text{kg}$, $1\\ \\text{m/s}$) yang bergerak searah di depannya. Jika tumbukan lenting sempurna, kecepatan benda B setelah tumbukan adalah ...", options: ["1,6 m/s", "5 m/s", "4,6 m/s", "2,9 m/s"], answer: 2, solution: "1. Diketahui $m_A = 3\\ \\text{kg}$, $v_A = 4\\ \\text{m/s}$, $m_B = 2\\ \\text{kg}$, $v_B = 1\\ \\text{m/s}$. 2. Gunakan $v_B' = \\frac{(m_B - m_A)v_B + 2m_A v_A}{m_A + m_B} = \\frac{(2-3)(1) + 2(3)(4)}{5} = \\frac{23}{5} = 4{,}6\\ \\text{m/s}$. 3. Jadi jawabannya 4,6 m/s." },
{ q: "Koefisien restitusi suatu tumbukan bernilai nol. Jenis tumbukan tersebut adalah ...", options: ["lenting sempurna", "tak lenting sama sekali", "lenting sebagian", "tumbukan elastis"], answer: 1, solution: "1. Koefisien restitusi $e$ menyatakan perbandingan kecepatan relatif setelah dan sebelum tumbukan. 2. Nilai $e = 1$ berarti lenting sempurna, $0 < e < 1$ lenting sebagian, dan $e = 0$ berarti kedua benda menyatu yaitu tumbukan tak lenting sama sekali. 3. Jadi jawabannya tak lenting sama sekali." },
{ q: "Peluru bermassa $20\\ \\text{g}$ ditembakkan $200\\ \\text{m/s}$ dan bersarang di balok kayu $1{,}98\\ \\text{kg}$ yang diam. Kecepatan balok sesaat setelah peluru bersarang adalah ...", options: ["200 m/s", "0,02 m/s", "2 m/s", "4 m/s"], answer: 2, solution: "1. Diketahui $m_p = 0{,}02\\ \\text{kg}$, $v_p = 200\\ \\text{m/s}$, $m_b = 1{,}98\\ \\text{kg}$ (tumbukan tak lenting). 2. Gunakan kekekalan momentum $m_p v_p = (m_p + m_b)v'$, sehingga $v' = \\frac{0{,}02 \\times 200}{2} = \\frac{4}{2} = 2\\ \\text{m/s}$. 3. Jadi jawabannya 2 m/s." },
{ q: "Bola $0{,}4\\ \\text{kg}$ datang $12\\ \\text{m/s}$, dipukul hingga berbalik arah dengan kecepatan $10\\ \\text{m/s}$. Jika selang waktu kontak $0{,}02\\ \\text{s}$, gaya rata-rata pemukul pada bola adalah ...", options: ["220 N", "440 N", "88 N", "4400 N"], answer: 1, solution: "1. Diketahui $m = 0{,}4\\ \\text{kg}$, $v_1 = -12\\ \\text{m/s}$, $v_2 = 10\\ \\text{m/s}$, $\\Delta t = 0{,}02\\ \\text{s}$. 2. Gunakan $F = \\frac{\\Delta p}{\\Delta t} = \\frac{0{,}4(10 - (-12))}{0{,}02} = \\frac{8{,}8}{0{,}02} = 440\\ \\text{N}$. 3. Jadi jawabannya 440 N." },
{ q: "Berikut ini yang merupakan penerapan prinsip kekekalan momentum dalam kehidupan sehari-hari adalah ...", options: ["mobil yang direm", "buku diam di atas meja", "lampu yang menyala", "roket yang meluncur"], answer: 3, solution: "1. Kekekalan momentum terjadi pada sistem tanpa gaya luar, misalnya semburan massa ke satu arah. 2. Roket meluncur karena gas panas disemburkan ke belakang sehingga badan roket terdorong ke depan; momentum total sistem tetap nol. 3. Jadi jawabannya roket yang meluncur." },
{ q: "Dua benda bermassa sama bertumbukan lenting sempurna, mula-mula benda kedua diam. Setelah tumbukan yang terjadi adalah ...", options: ["kedua benda menyatu dan diam", "kedua benda saling bertukar kecepatan", "kedua benda diam", "kecepatan masing-masing tetap"], answer: 1, solution: "1. Pada tumbukan lenting sempurna berlaku kekekalan momentum dan energi kinetik. 2. Untuk massa yang sama dengan satu benda mula-mula diam, penyelesaian kedua hukum kekekalan memberikan $v_1' = v_2$ dan $v_2' = v_1$, artinya kedua benda saling bertukar kecepatan. 3. Jadi jawabannya kedua benda saling bertukar kecepatan." },
{ q: "Pernyataan yang tepat mengenai impuls adalah ...", options: ["Impuls adalah perubahan energi", "Impuls sama dengan perubahan momentum dan bersatuan N s", "Impuls hanya ada pada tumbukan lenting", "Impuls bersatuan joule"], answer: 1, solution: "1. Impuls didefinisikan sebagai $I = F \\Delta t$. 2. Dari Hukum II Newton, $F \\Delta t = \\Delta p$, sehingga impuls sama dengan perubahan momentum dengan satuan $\\text{N s} = \\text{kg m/s}$, bukan joule. 3. Jadi jawabannya impuls sama dengan perubahan momentum dan bersatuan N s." },
{ q: "Tekanan hidrostatis pada kedalaman $5\\ \\text{m}$ di dalam air adalah ... ($\\rho_{air} = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$)", options: ["5 kPa", "50 kPa", "500 kPa", "50 Pa"], answer: 1, solution: "1. Diketahui $h = 5\\ \\text{m}$, $\\rho = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$. 2. Gunakan $P = \\rho g h = 1000 \\times 10 \\times 5 = 50000\\ \\text{Pa} = 50\\ \\text{kPa}$. 3. Jadi jawabannya 50 kPa." },
{ q: "Pada dongkrak hidrolik, gaya $50\\ \\text{N}$ pada piston kecil seluas $10\\ \\text{cm}^2$ digunakan untuk mengangkat beban pada piston besar seluas $200\\ \\text{cm}^2$. Gaya angkat pada piston besar adalah ...", options: ["1000 N", "100 N", "250 N", "2000 N"], answer: 0, solution: "1. Diketahui $F_1 = 50\\ \\text{N}$, $A_1 = 10\\ \\text{cm}^2$, $A_2 = 200\\ \\text{cm}^2$. 2. Gunakan Hukum Pascal $\\frac{F_1}{A_1} = \\frac{F_2}{A_2}$, sehingga $F_2 = 50 \\times \\frac{200}{10} = 1000\\ \\text{N}$. 3. Jadi jawabannya 1000 N." },
{ q: "Sebuah benda beratnya $800\\ \\text{N}$ di udara dan $600\\ \\text{N}$ saat tercelup seluruhnya di air. Volume benda tersebut adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["0,2 m^3", "0,002 m^3", "0,02 m^3", "2 m^3"], answer: 2, solution: "1. Gaya apung $F_A = 800 - 600 = 200\\ \\text{N}$. 2. Gunakan $F_A = \\rho g V$, sehingga $V = \\frac{200}{1000 \\times 10} = 0{,}02\\ \\text{m}^3$. 3. Jadi jawabannya 0,02 m^3." },
{ q: "Sebuah kapal bermassa $1200\\ \\text{kg}$ terapung di air laut ($\\rho = 1000\\ \\text{kg/m}^3$). Volume air yang dipindahkan kapal adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["12 m^3", "1,2 m^3", "0,12 m^3", "120 m^3"], answer: 1, solution: "1. Kapal terapung sehingga $F_A = W = 1200 \\times 10 = 12000\\ \\text{N}$. 2. Gunakan $F_A = \\rho g V$, sehingga $V = \\frac{12000}{1000 \\times 10} = 1{,}2\\ \\text{m}^3$. 3. Jadi jawabannya 1,2 m^3." },
{ q: "Tekanan total yang dialami penyelam pada kedalaman $10\\ \\text{m}$ di air laut adalah ... (tekanan udara luar $1 \\times 10^5\\ \\text{Pa}$, $\\rho = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$)", options: ["100 kPa", "300 kPa", "10 kPa", "200 kPa"], answer: 3, solution: "1. Diketahui $P_0 = 1 \\times 10^5\\ \\text{Pa}$, $h = 10\\ \\text{m}$. 2. Gunakan $P = P_0 + \\rho g h = 10^5 + (1000)(10)(10) = 10^5 + 10^5 = 2 \\times 10^5\\ \\text{Pa} = 200\\ \\text{kPa}$. 3. Jadi jawabannya 200 kPa." },
{ q: "Pipa kapiler berjari-jari $0{,}5\\ \\text{mm}$ dicelupkan ke air ($\\gamma = 0{,}072\\ \\text{N/m}$, sudut kontak $0^\\circ$). Kenaikan air dalam pipa adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["28,8 cm", "2,88 cm", "0,288 cm", "5,76 cm"], answer: 1, solution: "1. Diketahui $r = 5 \\times 10^{-4}\\ \\text{m}$, $\\cos 0^\\circ = 1$. 2. Gunakan $h = \\frac{2\\gamma \\cos\\theta}{\\rho g r} = \\frac{2(0{,}072)(1)}{1000 \\times 10 \\times 5 \\times 10^{-4}} = \\frac{0{,}144}{5} = 0{,}0288\\ \\text{m} = 2{,}88\\ \\text{cm}$. 3. Jadi jawabannya 2,88 cm." },
{ q: "Seekor nyamuk dapat berjalan di atas permukaan air tanpa tenggelam. Hal ini disebabkan oleh ...", options: ["massa jenis nyamuk yang kecil", "tekanan udara", "gaya apung yang besar", "tegangan permukaan air"], answer: 3, solution: "1. Kaki nyamuk tidak menembus permukaan air melainkan sedikit melengkungkan permukaan. 2. Molekul-molekul permukaan air saling tarik-menarik membentuk lapisan elastis (tegangan permukaan) yang mampu menahan berat nyamuk yang sangat kecil. 3. Jadi jawabannya tegangan permukaan air." },
{ q: "Dongkrak hidrolik mengangkat beban $1500\\ \\text{N}$ dengan gaya $100\\ \\text{N}$ pada piston kecil seluas $5\\ \\text{cm}^2$. Luas piston besar adalah ...", options: ["7,5 cm^2", "15 cm^2", "75 cm^2", "750 cm^2"], answer: 2, solution: "1. Diketahui $F_2 = 1500\\ \\text{N}$, $F_1 = 100\\ \\text{N}$, $A_1 = 5\\ \\text{cm}^2$. 2. Gunakan $\\frac{F_1}{A_1} = \\frac{F_2}{A_2}$, sehingga $A_2 = 5 \\times \\frac{1500}{100} = 75\\ \\text{cm}^2$. 3. Jadi jawabannya 75 cm^2." },
{ q: "Balok bervolume $0{,}6\\ \\text{m}^3$ tercelup $\\frac{3}{4}$ bagian di dalam air. Gaya apung yang dialami balok adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["4500 N", "6000 N", "450 N", "3000 N"], answer: 0, solution: "1. Volume tercelup $V = \\frac{3}{4} \\times 0{,}6 = 0{,}45\\ \\text{m}^3$. 2. Gunakan $F_A = \\rho g V = 1000 \\times 10 \\times 0{,}45 = 4500\\ \\text{N}$. 3. Jadi jawabannya 4500 N." },
{ q: "Permukaan raksa justru turun (cekung) di dalam pipa kapiler kaca. Hal ini terjadi karena ...", options: ["tegangan permukaan nol", "kohesi raksa lebih besar daripada adhesinya dengan kaca", "massa jenis raksa kecil", "adhesi lebih besar daripada kohesi"], answer: 1, solution: "1. Kapilaritas ditentukan oleh perbandingan gaya kohesi (antarpartikel zat cair) dan adhesi (zat cair dengan dinding). 2. Pada raksa, kohesi antarpartikel raksa lebih kuat daripada adhesi raksa-kaca, sehingga permukaan raksa tertarik ke bawah membentuk meniskus cekung. 3. Jadi jawabannya kohesi raksa lebih besar daripada adhesinya dengan kaca." },
{ q: "Menurut Hukum Pascal, tekanan yang diberikan pada fluida dalam ruang tertutup akan ...", options: ["hanya diteruskan ke bawah", "diteruskan sama besar ke segala arah", "hilang diserap fluida", "hanya bekerja pada piston kecil"], answer: 2, solution: "1. Hukum Pascal menyatakan tekanan yang diberikan pada fluida tertutup diteruskan tanpa berkurang. 2. Tekanan tersebut diteruskan sama besar ke setiap bagian fluida dan dinding bejana, ke segala arah. 3. Jadi jawabannya diteruskan sama besar ke segala arah." },
{ q: "Dua bejana berhubungan berbentuk berbeda diisi air hingga ketinggian sama. Tekanan hidrostatis di dasar kedua bejana ...", options: ["sama besar karena hanya bergantung pada kedalaman dan massa jenis", "lebih besar pada bejana yang lebar", "lebih besar pada bejana yang sempit", "bergantung pada volume air"], answer: 0, solution: "1. Tekanan hidrostatis dirumuskan $P = \\rho g h$. 2. Rumus tersebut tidak memuat bentuk atau luas bejana, sehingga dengan kedalaman dan jenis fluida yang sama tekanannya sama besar. 3. Jadi jawabannya sama besar karena hanya bergantung pada kedalaman dan massa jenis." },
{ q: "Sebuah benda dapat melayang (tidak tenggelam, tidak terapung) di dalam fluida jika ...", options: ["berat benda nol", "massa jenis benda lebih besar dari fluida", "massa jenis benda sama dengan massa jenis fluida", "massa jenis benda lebih kecil dari fluida"], answer: 2, solution: "1. Benda melayang berarti gaya apung tepat mengimbangi berat benda ($F_A = W$). 2. Karena $F_A = \\rho_f g V$ dan $W = \\rho_b g V$ dengan volume tercelup sama, syaratnya $\\rho_b = \\rho_f$. 3. Jadi jawabannya massa jenis benda sama dengan massa jenis fluida." },
{ q: "Batang logam panjangnya $2\\ \\text{m}$ dipanaskan sehingga suhunya naik $50^\\circ\\text{C}$. Jika koefisien muai panjang $1{,}2 \\times 10^{-5}/^\\circ\\text{C}$, pertambahan panjang batang adalah ...", options: ["1,2 mm", "12 mm", "0,12 mm", "120 mm"], answer: 0, solution: "1. Diketahui $L_0 = 2\\ \\text{m}$, $\\Delta T = 50^\\circ\\text{C}$, $\\alpha = 1{,}2 \\times 10^{-5}/^\\circ\\text{C}$. 2. Gunakan $\\Delta L = L_0 \\alpha \\Delta T = 2 \\times 1{,}2 \\times 10^{-5} \\times 50 = 1{,}2 \\times 10^{-3}\\ \\text{m} = 1{,}2\\ \\text{mm}$. 3. Jadi jawabannya 1,2 mm." },
{ q: "Sebanyak $0{,}5\\ \\text{kg}$ air dipanaskan dari $20^\\circ\\text{C}$ menjadi $60^\\circ\\text{C}$. Kalor yang diperlukan adalah ... ($c_{air} = 4200\\ \\text{J/kg}^\\circ\\text{C}$)", options: ["8,4 kJ", "840 kJ", "16,8 kJ", "84 kJ"], answer: 3, solution: "1. Diketahui $m = 0{,}5\\ \\text{kg}$, $\\Delta T = 40^\\circ\\text{C}$, $c = 4200\\ \\text{J/kg}^\\circ\\text{C}$. 2. Gunakan $Q = mc\\Delta T = 0{,}5 \\times 4200 \\times 40 = 84000\\ \\text{J} = 84\\ \\text{kJ}$. 3. Jadi jawabannya 84 kJ." },
{ q: "Air $200\\ \\text{g}$ bersuhu $80^\\circ\\text{C}$ dicampur dengan air $300\\ \\text{g}$ bersuhu $20^\\circ\\text{C}$ dalam wadah terisolasi. Suhu campuran adalah ...", options: ["44 C", "50 C", "40 C", "100 C"], answer: 0, solution: "1. Diketahui $m_1 = 200\\ \\text{g}$, $T_1 = 80^\\circ\\text{C}$, $m_2 = 300\\ \\text{g}$, $T_2 = 20^\\circ\\text{C}$. 2. Gunakan Asas Black $T_c = \\frac{m_1 T_1 + m_2 T_2}{m_1 + m_2} = \\frac{200 \\times 80 + 300 \\times 20}{500} = \\frac{22000}{500} = 44^\\circ\\text{C}$. 3. Jadi jawabannya 44 C." },
{ q: "Kalor yang dibutuhkan untuk meleburkan $2\\ \\text{kg}$ es bersuhu $0^\\circ\\text{C}$ seluruhnya menjadi air $0^\\circ\\text{C}$ adalah ... ($L_{es} = 336000\\ \\text{J/kg}$)", options: ["336 kJ", "672 kJ", "67,2 kJ", "1344 kJ"], answer: 1, solution: "1. Diketahui $m = 2\\ \\text{kg}$, $L = 336000\\ \\text{J/kg}$, tidak ada perubahan suhu. 2. Gunakan $Q = mL = 2 \\times 336000 = 672000\\ \\text{J} = 672\\ \\text{kJ}$. 3. Jadi jawabannya 672 kJ." },
{ q: "Suatu gas menerima kalor $800\\ \\text{J}$ dan melakukan usaha $300\\ \\text{J}$ terhadap lingkungannya. Perubahan energi dalam gas adalah ...", options: ["1100 J", "-500 J", "500 J", "300 J"], answer: 2, solution: "1. Diketahui $Q = +800\\ \\text{J}$ (menerima kalor) dan $W = +300\\ \\text{J}$ (melakukan usaha). 2. Gunakan Hukum I Termodinamika $\\Delta U = Q - W = 800 - 300 = 500\\ \\text{J}$. 3. Jadi jawabannya 500 J." },
{ q: "Mesin Carnot bekerja antara reservoir bersuhu $900\\ \\text{K}$ dan $300\\ \\text{K}$. Efisiensi mesin tersebut adalah ...", options: ["66,7%", "33,3%", "50%", "75%"], answer: 0, solution: "1. Diketahui $T_1 = 900\\ \\text{K}$ dan $T_2 = 300\\ \\text{K}$. 2. Gunakan $\\eta = \\left(1 - \\frac{T_2}{T_1}\\right) \\times 100\\% = \\left(1 - \\frac{300}{900}\\right) \\times 100\\% = 66{,}7\\%$. 3. Jadi jawabannya 66,7%." },
{ q: "Sebuah mesin kalor menyerap kalor $1200\\ \\text{J}$ tiap siklus dengan efisiensi $25\\%$. Usaha yang dihasilkan tiap siklus adalah ...", options: ["4800 J", "900 J", "1200 J", "300 J"], answer: 3, solution: "1. Diketahui $Q_1 = 1200\\ \\text{J}$ dan $\\eta = 25\\% = 0{,}25$. 2. Gunakan $\\eta = \\frac{W}{Q_1}$, sehingga $W = 0{,}25 \\times 1200 = 300\\ \\text{J}$. 3. Jadi jawabannya 300 J." },
{ q: "Pernyataan yang sesuai dengan Hukum II Termodinamika adalah ...", options: ["Mesin kalor dapat memiliki efisiensi 100%", "Energi dapat diciptakan dari ketiadaan", "Kalor tidak dapat berpindah spontan dari benda dingin ke benda panas tanpa usaha luar", "Entropi semesta selalu berkurang"], answer: 2, solution: "1. Hukum II Termodinamika membatasi arah perpindahan kalor dan efisiensi mesin kalor. 2. Menurut Clausius, kalor tidak dapat mengalir spontan dari suhu rendah ke suhu tinggi tanpa usaha dari luar, dan tidak ada mesin kalor yang efisiensinya 100%. 3. Jadi jawabannya kalor tidak dapat berpindah spontan dari benda dingin ke benda panas tanpa usaha luar." },
{ q: "Sebanyak $50\\ \\text{L}$ bensin ($\\gamma = 9{,}5 \\times 10^{-4}/^\\circ\\text{C}$) mengalami kenaikan suhu $30^\\circ\\text{C}$. Pertambahan volume bensin adalah ...", options: ["14,25 L", "0,1425 L", "1,425 L", "4,275 L"], answer: 2, solution: "1. Diketahui $V_0 = 50\\ \\text{L}$, $\\gamma = 9{,}5 \\times 10^{-4}/^\\circ\\text{C}$, $\\Delta T = 30^\\circ\\text{C}$. 2. Gunakan $\\Delta V = V_0 \\gamma \\Delta T = 50 \\times 9{,}5 \\times 10^{-4} \\times 30 = 1{,}425\\ \\text{L}$. 3. Jadi jawabannya 1,425 L." },
{ q: "Es $0{,}5\\ \\text{kg}$ bersuhu $-10^\\circ\\text{C}$ dipanaskan hingga menjadi air $20^\\circ\\text{C}$. Total kalor yang diperlukan adalah ... ($c_{es} = 2100$, $L = 336000$, $c_{air} = 4200$ dalam satuan SI)", options: ["220,5 kJ", "210 kJ", "178,5 kJ", "231 kJ"], answer: 0, solution: "1. Tahapannya: panaskan es $Q_1 = 0{,}5 \\times 2100 \\times 10 = 10500\\ \\text{J}$; leburkan es $Q_2 = 0{,}5 \\times 336000 = 168000\\ \\text{J}$; panaskan air $Q_3 = 0{,}5 \\times 4200 \\times 20 = 42000\\ \\text{J}$. 2. Jumlahkan $Q = 10500 + 168000 + 42000 = 220500\\ \\text{J} = 220{,}5\\ \\text{kJ}$. 3. Jadi jawabannya 220,5 kJ." },
{ q: "Pada proses termodinamika berikut, usaha yang dilakukan gas sama dengan nol pada proses ...", options: ["isobarik", "isotermik", "isokhorik", "adiabatik"], answer: 2, solution: "1. Usaha gas dirumuskan $W = P\\Delta V$. 2. Pada proses isokhorik volume tetap ($\\Delta V = 0$) sehingga tidak ada usaha yang dilakukan gas. 3. Jadi jawabannya isokhorik." },
{ q: "Dua balok tembaga sejenis, balok P bermassa $1\\ \\text{kg}$ dan balok Q bermassa $2\\ \\text{kg}$, diberi kalor yang sama. Kenaikan suhu yang terjadi adalah ...", options: ["sama besar", "balok Q lebih besar", "nol", "balok P lebih besar"], answer: 3, solution: "1. Kapasitas kalor $C = mc$ bergantung pada massa; kalor jenis sama tetapi massa berbeda. 2. Dari $Q = mc\\Delta T$, untuk $Q$ sama maka $\\Delta T = \\frac{Q}{mc}$; massa P lebih kecil sehingga $\\Delta T$ balok P lebih besar. 3. Jadi jawabannya balok P lebih besar." },
{ q: "Tubuh terasa dingin saat keringat menguap. Hal ini terjadi karena ...", options: ["keringat menaikkan suhu tubuh", "penguapan menghambat panas", "angin saja yang mendinginkan", "penguapan memerlukan kalor yang diambil dari tubuh"], answer: 3, solution: "1. Penguapan adalah perubahan wujud cair menjadi gas. 2. Perubahan wujud memerlukan kalor laten yang diambil dari lingkungan terdekat, yaitu permukaan kulit dan tubuh. 3. Jadi jawabannya penguapan memerlukan kalor yang diambil dari tubuh." },
{ q: "Gelombang merambat dengan panjang gelombang $2\\ \\text{m}$ dan frekuensi $50\\ \\text{Hz}$. Cepat rambat gelombang adalah ...", options: ["25 m/s", "200 m/s", "100 m/s", "0,04 m/s"], answer: 2, solution: "1. Diketahui $\\lambda = 2\\ \\text{m}$ dan $f = 50\\ \\text{Hz}$. 2. Gunakan $v = \\lambda f = 2 \\times 50 = 100\\ \\text{m/s}$. 3. Jadi jawabannya 100 m/s." },
{ q: "Gelombang merambat $5\\ \\text{m/s}$ dengan panjang gelombang $0{,}25\\ \\text{m}$. Periode gelombang tersebut adalah ...", options: ["0,05 s", "20 s", "1,25 s", "4 s"], answer: 0, solution: "1. Diketahui $v = 5\\ \\text{m/s}$ dan $\\lambda = 0{,}25\\ \\text{m}$. 2. Cari frekuensi $f = \\frac{v}{\\lambda} = \\frac{5}{0{,}25} = 20\\ \\text{Hz}$, lalu $T = \\frac{1}{f} = \\frac{1}{20} = 0{,}05\\ \\text{s}$. 3. Jadi jawabannya 0,05 s." },
{ q: "Sumber bunyi $600\\ \\text{Hz}$ bergerak mendekati pengamat diam dengan kecepatan $20\\ \\text{m/s}$. Frekuensi yang didengar pengamat adalah ... (cepat rambat bunyi $340\\ \\text{m/s}$)", options: ["566,7 Hz", "600 Hz", "675 Hz", "637,5 Hz"], answer: 3, solution: "1. Diketahui $f_s = 600\\ \\text{Hz}$, $v_s = 20\\ \\text{m/s}$ mendekat, $v = 340\\ \\text{m/s}$. 2. Gunakan Efek Doppler $f_p = \\frac{v}{v - v_s} f_s = \\frac{340}{340 - 20} \\times 600 = \\frac{340}{320} \\times 600 = 637{,}5\\ \\text{Hz}$. 3. Jadi jawabannya 637,5 Hz." },
{ q: "Sirene $680\\ \\text{Hz}$ pada mobil yang menjauhi pendengar diam dengan kecepatan $30\\ \\text{m/s}$. Frekuensi yang didengar adalah ... ($v_{bunyi} = 340\\ \\text{m/s}$)", options: ["625 Hz", "745,8 Hz", "680 Hz", "340 Hz"], answer: 0, solution: "1. Diketahui $f_s = 680\\ \\text{Hz}$, $v_s = 30\\ \\text{m/s}$ menjauh. 2. Gunakan $f_p = \\frac{v}{v + v_s} f_s = \\frac{340}{340 + 30} \\times 680 = \\frac{340}{370} \\times 680 = 624{,}9\\ \\text{Hz} \\approx 625\\ \\text{Hz}$. 3. Jadi jawabannya 625 Hz." },
{ q: "Intensitas bunyi $10^{-6}\\ \\text{W/m}^2$ memiliki taraf intensitas sebesar ... ($I_0 = 10^{-12}\\ \\text{W/m}^2$)", options: ["6 dB", "60 dB", "120 dB", "10 dB"], answer: 1, solution: "1. Diketahui $I = 10^{-6}\\ \\text{W/m}^2$ dan $I_0 = 10^{-12}\\ \\text{W/m}^2$. 2. Gunakan $TI = 10 \\log\\frac{I}{I_0} = 10 \\log(10^6) = 10 \\times 6 = 60\\ \\text{dB}$. 3. Jadi jawabannya 60 dB." },
{ q: "Taraf intensitas sebuah sumber bunyi bertambah $20\\ \\text{dB}$. Intensitas bunyinya menjadi ... kali semula.", options: ["100 kali", "20 kali", "10 kali", "2 kali"], answer: 0, solution: "1. Selisih taraf intensitas $\\Delta TI = 10 \\log\\frac{I_2}{I_1} = 20\\ \\text{dB}$. 2. Maka $\\log\\frac{I_2}{I_1} = 2$, sehingga $\\frac{I_2}{I_1} = 10^2 = 100$. 3. Jadi jawabannya 100 kali." },
{ q: "Kolom udara tertutup sepanjang $0{,}5\\ \\text{m}$ beresonansi pada nada dasarnya. Frekuensi resonansi tersebut adalah ... (cepat rambat bunyi $340\\ \\text{m/s}$)", options: ["85 Hz", "340 Hz", "170 Hz", "68 Hz"], answer: 2, solution: "1. Pada kolom tertutup, resonansi pertama memenuhi $L = \\frac{\\lambda}{4}$, sehingga $\\lambda = 4 \\times 0{,}5 = 2\\ \\text{m}$. 2. Gunakan $f = \\frac{v}{\\lambda} = \\frac{340}{2} = 170\\ \\text{Hz}$. 3. Jadi jawabannya 170 Hz." },
{ q: "Senar gitar dipetik lalu panjang senar yang bergetar diperpendek setengahnya. Nada yang dihasilkan menjadi ...", options: ["lebih rendah", "lebih tinggi", "tetap", "hilang"], answer: 1, solution: "1. Frekuensi nada dasar dawai $f_0 = \\frac{v}{2L}$ berbanding terbalik dengan panjang dawai. 2. Jika $L$ diperkecil, frekuensi membesar sehingga nada terdengar lebih tinggi. 3. Jadi jawabannya lebih tinggi." },
{ q: "Perbedaan pola harmonik pipa organa terbuka dan tertutup adalah ...", options: ["keduanya hanya menghasilkan harmonik ganjil", "tertutup menghasilkan semua harmonik", "tidak ada perbedaan", "terbuka menghasilkan semua harmonik, tertutup hanya harmonik ganjil"], answer: 3, solution: "1. Pipa terbuka memiliki perut di kedua ujung sehingga semua kelipatan harmonik ($n = 1, 2, 3, ...$) dapat terjadi. 2. Pipa tertutup memiliki simpul di ujung tertutup sehingga hanya harmonik ganjil ($n = 1, 3, 5, ...$) yang terjadi. 3. Jadi jawabannya terbuka menghasilkan semua harmonik, tertutup hanya harmonik ganjil." },
{ q: "Dua gelombang berinterferensi saling menguatkan (konstruktif) jika selisih lintasan keduanya sebesar ...", options: ["(n + 1/2) lambda", "lambda/4", "nol", "n lambda"], answer: 3, solution: "1. Interferensi konstruktif terjadi saat kedua gelombang tiba dalam fase yang sama (puncak bertemu puncak). 2. Syaratnya selisih lintasan merupakan kelipatan bulat panjang gelombang, yaitu $n\\lambda$ dengan $n = 0, 1, 2, ...$. 3. Jadi jawabannya n lambda." },
{ q: "Bunyi ledakan di ruang hampa udara tidak dapat didengar karena ...", options: ["bunyi memerlukan medium untuk merambat", "bunyi merambat paling cepat di vakum", "bunyi adalah gelombang elektromagnetik", "bunyi merambat tanpa energi"], answer: 0, solution: "1. Bunyi adalah gelombang mekanik yang merambat melalui getaran partikel medium. 2. Ruang hampa tidak memiliki partikel medium sehingga tidak ada yang dirambatkan dan bunyi tidak terdengar. 3. Jadi jawabannya bunyi memerlukan medium untuk merambat." },
{ q: "Pengamat bergerak mendekati sumber bunyi diam $500\\ \\text{Hz}$ dengan kecepatan $10\\ \\text{m/s}$. Frekuensi yang didengar pengamat adalah ... ($v_{bunyi} = 340\\ \\text{m/s}$)", options: ["485,3 Hz", "500 Hz", "514,7 Hz", "529,4 Hz"], answer: 2, solution: "1. Diketahui $f_s = 500\\ \\text{Hz}$, $v_p = 10\\ \\text{m/s}$ mendekat, $v_s = 0$. 2. Gunakan $f_p = \\frac{v + v_p}{v} f_s = \\frac{340 + 10}{340} \\times 500 = \\frac{350}{340} \\times 500 = 514{,}7\\ \\text{Hz}$. 3. Jadi jawabannya 514,7 Hz." },
{ q: "Ayunan bandul akan berayun paling kuat ketika didorong secara periodik. Peristiwa ini disebut resonansi yang terjadi saat ...", options: ["amplitudo pendorong sangat besar", "mediumnya vakum", "suhunya tinggi", "frekuensi pendorong sama dengan frekuensi alami bandul"], answer: 3, solution: "1. Resonansi adalah ikut bergetarnya suatu benda dengan amplitudo maksimum. 2. Hal ini terjadi ketika frekuensi gaya pemaksa (pendorong) sama dengan frekuensi alami benda. 3. Jadi jawabannya frekuensi pendorong sama dengan frekuensi alami bandul." },
{ q: "Benda diletakkan $20\\ \\text{cm}$ di depan cermin cekung berjarak fokus $15\\ \\text{cm}$. Jarak bayangan yang terbentuk adalah ...", options: ["60 cm", "15 cm", "7,5 cm", "30 cm"], answer: 0, solution: "1. Diketahui $s = 20\\ \\text{cm}$ dan $f = 15\\ \\text{cm}$. 2. Gunakan $\\frac{1}{f} = \\frac{1}{s} + \\frac{1}{s'}$, sehingga $\\frac{1}{s'} = \\frac{1}{15} - \\frac{1}{20} = \\frac{4-3}{60} = \\frac{1}{60}$, jadi $s' = 60\\ \\text{cm}$. 3. Jadi jawabannya 60 cm." },
{ q: "Benda diletakkan $30\\ \\text{cm}$ di depan cermin cembung yang jarak fokusnya $20\\ \\text{cm}$. Letak bayangan yang terbentuk adalah ...", options: ["60 cm di depan cermin", "12 cm di depan cermin", "60 cm di belakang cermin", "12 cm di belakang cermin"], answer: 3, solution: "1. Diketahui $s = 30\\ \\text{cm}$ dan $f = -20\\ \\text{cm}$ (cermin cembung fokus negatif). 2. Gunakan $\\frac{1}{s'} = \\frac{1}{f} - \\frac{1}{s} = \\frac{1}{-20} - \\frac{1}{30} = \\frac{-5}{60}$, sehingga $s' = -12\\ \\text{cm}$ (tanda negatif = maya di belakang cermin). 3. Jadi jawabannya 12 cm di belakang cermin." },
{ q: "Benda diletakkan $12\\ \\text{cm}$ di depan lensa cembung berjarak fokus $8\\ \\text{cm}$. Jarak bayangan dari lensa adalah ...", options: ["8 cm", "24 cm", "12 cm", "6 cm"], answer: 1, solution: "1. Diketahui $s = 12\\ \\text{cm}$ dan $f = 8\\ \\text{cm}$. 2. Gunakan $\\frac{1}{s'} = \\frac{1}{f} - \\frac{1}{s} = \\frac{1}{8} - \\frac{1}{12} = \\frac{3-2}{24} = \\frac{1}{24}$, sehingga $s' = 24\\ \\text{cm}$. 3. Jadi jawabannya 24 cm." },
{ q: "Benda diletakkan $18\\ \\text{cm}$ di depan lensa cekung yang jarak fokusnya $9\\ \\text{cm}$. Letak bayangan yang terbentuk adalah ...", options: ["6 cm di depan lensa", "18 cm di depan lensa", "6 cm di belakang lensa", "tidak terbentuk bayangan"], answer: 2, solution: "1. Diketahui $s = 18\\ \\text{cm}$ dan $f = -9\\ \\text{cm}$ (lensa cekung fokus negatif). 2. Gunakan $\\frac{1}{s'} = \\frac{1}{f} - \\frac{1}{s} = \\frac{1}{-9} - \\frac{1}{18} = \\frac{-3}{18} = -\\frac{1}{6}$, sehingga $s' = -6\\ \\text{cm}$ (maya, di sisi benda). 3. Jadi jawabannya 6 cm di depan lensa." },
{ q: "Seberkas cahaya datang dari udara ($n = 1$) ke kaca ($n = 1{,}5$) dengan sudut datang $30^\\circ$. Sudut biasnya adalah ...", options: ["19,5 C", "30 C", "48,6 C", "15 C"], answer: 0, solution: "1. Diketahui $n_1 = 1$, $\\theta_1 = 30^\\circ$, $n_2 = 1{,}5$. 2. Gunakan Hukum Snellius $n_1 \\sin\\theta_1 = n_2 \\sin\\theta_2$, sehingga $\\sin\\theta_2 = \\frac{1 \\times 0{,}5}{1{,}5} = \\frac{1}{3}$, jadi $\\theta_2 \\approx 19{,}5^\\circ$. 3. Jadi jawabannya 19,5 C." },
{ q: "Mikroskop memiliki jarak fokus lensa objektif $1\\ \\text{cm}$ dan okuler $5\\ \\text{cm}$. Benda diletakkan $1{,}1\\ \\text{cm}$ dari objektif. Perbesaran total untuk mata berakomodasi maksimum adalah ... (titik dekat $25\\ \\text{cm}$)", options: ["60x", "16x", "50x", "10x"], answer: 0, solution: "1. Jarak bayangan objektif $s'_{ob} = \\frac{1{,}1 \\times 1}{1{,}1 - 1} = 11\\ \\text{cm}$, sehingga $M_{ob} = \\frac{11}{1{,}1} = 10$. 2. Perbesaran okuler saat berakomodasi maksimum $M_{ok} = \\frac{25}{5} + 1 = 6$. 3. Perbesaran total $M = 10 \\times 6 = 60$, jadi jawabannya 60x." },
{ q: "Teropong bintang memiliki fokus objektif $100\\ \\text{cm}$ dan fokus okuler $5\\ \\text{cm}$. Perbesaran teropong untuk mata tak berakomodasi adalah ...", options: ["20 kali", "105 kali", "500 kali", "5 kali"], answer: 0, solution: "1. Diketahui $f_{ob} = 100\\ \\text{cm}$ dan $f_{ok} = 5\\ \\text{cm}$. 2. Gunakan $M = \\frac{f_{ob}}{f_{ok}} = \\frac{100}{5} = 20$. 3. Jadi jawabannya 20 kali." },
{ q: "Perbesaran maksimum sebuah lup diperoleh ketika ...", options: ["mata tak berakomodasi", "benda tepat di titik fokus", "bayangan di tak hingga", "mata berakomodasi maksimum"], answer: 3, solution: "1. Perbesaran lup untuk mata tak berakomodasi adalah $M = \\frac{25}{f}$, sedangkan untuk mata berakomodasi maksimum $M = \\frac{25}{f} + 1$. 2. Nilai $\\frac{25}{f} + 1$ selalu lebih besar daripada $\\frac{25}{f}$, sehingga perbesaran maksimum terjadi saat mata berakomodasi maksimum. 3. Jadi jawabannya mata berakomodasi maksimum." },
{ q: "Sifat bayangan yang dibentuk cermin datar adalah ...", options: ["nyata, terbalik, diperbesar", "nyata, tegak, diperkecil", "maya, terbalik, sama besar", "maya, tegak, sama besar"], answer: 3, solution: "1. Cermin datar memantulkan cahaya tanpa memfokuskannya sehingga bayangan bersifat maya. 2. Bayangan tegak, berukuran sama dengan benda, dan jarak bayangan ke cermin sama dengan jarak benda. 3. Jadi jawabannya maya, tegak, sama besar." },
{ q: "Sedotan dalam gelas berisi air tampak bengkok pada permukaan air. Peristiwa ini terjadi karena ...", options: ["pemantulan sempurna", "difraksi cahaya", "pembiasan cahaya dari air ke udara menjauhi garis normal", "cermin datar"], answer: 2, solution: "1. Cahaya dari sedotan di dalam air merambat ke udara, yaitu dari medium rapat ke medium renggang. 2. Menurut Hukum Snellius, cahaya yang menuju medium renggang dibiaskan menjauhi garis normal sehingga posisi sedotan tampak bergeser dan terlihat bengkok. 3. Jadi jawabannya pembiasan cahaya dari air ke udara menjauhi garis normal." },
{ q: "Indeks bias kaca adalah $1{,}5$. Cepat rambat cahaya di dalam kaca dibandingkan di vakum adalah ...", options: ["sama besar", "lebih besar", "lebih kecil", "nol"], answer: 2, solution: "1. Indeks bias didefinisikan $n = \\frac{c}{v}$, dengan $c$ cepat rambat di vakum. 2. Karena $n = 1{,}5 > 1$, maka $v = \\frac{c}{1{,}5} < c$, artinya cahaya merambat lebih lambat di dalam kaca. 3. Jadi jawabannya lebih kecil." },
{ q: "Kaca spion kendaraan menggunakan cermin cembung karena ...", options: ["menghasilkan bayangan nyata diperbesar", "tidak membentuk bayangan", "bayangan maya, tegak, diperkecil sehingga jangkauan pandang luas", "bayangan sama besar dengan benda"], answer: 2, solution: "1. Cermin cembung selalu membentuk bayangan maya, tegak, dan diperkecil. 2. Bayangan yang diperkecil membuat daerah pantulan yang tertangkap lebih luas sehingga pengemudi melihat jangkauan lebih lebar. 3. Jadi jawabannya bayangan maya, tegak, diperkecil sehingga jangkauan pandang luas." },
{ q: "Dua muatan $2\\ \\mu\\ \\text{C}$ dan $3\\ \\mu\\ \\text{C}$ terpisah $0{,}3\\ \\text{m}$ di udara. Besar gaya Coulomb keduanya adalah ... ($k = 9 \\times 10^9\\ \\text{N m}^2/\\text{C}^2$)", options: ["0,6 N", "6 N", "0,06 N", "60 N"], answer: 0, solution: "1. Diketahui $q_1 = 2 \\times 10^{-6}\\ \\text{C}$, $q_2 = 3 \\times 10^{-6}\\ \\text{C}$, $r = 0{,}3\\ \\text{m}$. 2. Gunakan $F = k\\frac{q_1 q_2}{r^2} = 9 \\times 10^9 \\times \\frac{6 \\times 10^{-12}}{0{,}09} = \\frac{5{,}4 \\times 10^{-2}}{9 \\times 10^{-2}} = 0{,}6\\ \\text{N}$. 3. Jadi jawabannya 0,6 N." },
{ q: "Kuat medan listrik pada jarak $0{,}2\\ \\text{m}$ dari muatan $4\\ \\mu\\ \\text{C}$ adalah ...", options: ["$3{,}6\\times 10^4\\ \\text{N/C}$", "$9\\times 10^4\\ \\text{N/C}$", "$9\\times 10^5\\ \\text{N/C}$", "$9\\times 10^6\\ \\text{N/C}$"], answer: 2, solution: "1. Diketahui $Q = 4 \\times 10^{-6}\\ \\text{C}$ dan $r = 0{,}2\\ \\text{m}$. 2. Gunakan $E = k\\frac{Q}{r^2} = 9 \\times 10^9 \\times \\frac{4 \\times 10^{-6}}{0{,}04} = \\frac{3{,}6 \\times 10^4}{4 \\times 10^{-2}} = 9 \\times 10^5\\ \\text{N/C}$. 3. Jadi jawabannya $9\\times 10^5\\ \\text{N/C}$." },
{ q: "Potensial listrik pada jarak $0{,}3\\ \\text{m}$ dari muatan $2\\ \\mu\\ \\text{C}$ adalah ...", options: ["6 kV", "60 kV", "600 kV", "18 kV"], answer: 1, solution: "1. Diketahui $Q = 2 \\times 10^{-6}\\ \\text{C}$ dan $r = 0{,}3\\ \\text{m}$. 2. Gunakan $V = k\\frac{Q}{r} = 9 \\times 10^9 \\times \\frac{2 \\times 10^{-6}}{0{,}3} = \\frac{1{,}8 \\times 10^4}{3 \\times 10^{-1}} = 6 \\times 10^4\\ \\text{V} = 60\\ \\text{kV}$. 3. Jadi jawabannya 60 kV." },
{ q: "Dua muatan listrik sejenis didekatkan satu sama lain. Energi potensial sistem kedua muatan tersebut bernilai ...", options: ["negatif", "nol", "positif", "tak hingga"], answer: 2, solution: "1. Energi potensial listrik $E_p = k\\frac{q_1 q_2}{r}$. 2. Untuk muatan sejenis, $q_1 q_2 > 0$ sehingga $E_p$ positif; diperlukan usaha luar untuk mendekatkan keduanya melawan gaya tolak. 3. Jadi jawabannya positif." },
{ q: "Tiga hambatan $2\\ \\Omega$, $4\\ \\Omega$, dan $6\\ \\Omega$ dirangkai paralel. Hambatan penggantinya adalah ...", options: ["12 ohm", "1,09 ohm", "11 ohm", "0,09 ohm"], answer: 1, solution: "1. Gunakan $\\frac{1}{R_p} = \\frac{1}{2} + \\frac{1}{4} + \\frac{1}{6} = \\frac{6+3+2}{12} = \\frac{11}{12}$. 2. Maka $R_p = \\frac{12}{11} = 1{,}09\\ \\Omega$. 3. Jadi jawabannya 1,09 ohm." },
{ q: "Hambatan $2\\ \\Omega$ dirangkai seri dengan kombinasi paralel dua hambatan $4\\ \\Omega$. Rangkaian dihubungkan ke tegangan $12\\ \\text{V}$. Kuat arus total yang mengalir adalah ...", options: ["6 A", "2 A", "1,5 A", "3 A"], answer: 3, solution: "1. Paralel dua hambatan $4\\ \\Omega$ menghasilkan $R_p = 2\\ \\Omega$; seri dengan $2\\ \\Omega$ menjadi $R_{total} = 4\\ \\Omega$. 2. Gunakan Hukum Ohm $I = \\frac{V}{R} = \\frac{12}{4} = 3\\ \\text{A}$. 3. Jadi jawabannya 3 A." },
{ q: "Elemen pemanas berhambatan $50\\ \\Omega$ dipasang pada tegangan $200\\ \\text{V}$. Daya listrik elemen tersebut adalah ...", options: ["800 W", "400 W", "4 W", "1600 W"], answer: 0, solution: "1. Diketahui $R = 50\\ \\Omega$ dan $V = 200\\ \\text{V}$. 2. Gunakan $P = \\frac{V^2}{R} = \\frac{200^2}{50} = \\frac{40000}{50} = 800\\ \\text{W}$. 3. Jadi jawabannya 800 W." },
{ q: "Satuan kWh yang tertera pada tagihan listrik PLN menyatakan besaran ...", options: ["daya", "energi", "tegangan", "arus"], answer: 1, solution: "1. Satuan kWh adalah kilowatt-hour, yaitu daya (kW) dikali waktu (hour). 2. Daya dikali waktu menghasilkan energi, sehingga kWh adalah satuan energi listrik yang dipakai. 3. Jadi jawabannya energi." },
{ q: "Arah arus listrik konvensional dalam kawat penghantar adalah ...", options: ["searah gerak elektron", "tegak lurus gerak elektron", "berlawanan arah dengan gerak elektron", "tidak berkaitan dengan elektron"], answer: 2, solution: "1. Pembawa muatan dalam logam adalah elektron yang bergerak dari kutub negatif ke positif. 2. Secara konvensi, arah arus listrik ditetapkan berlawanan dengan arah gerak elektron, yaitu dari potensial tinggi ke rendah. 3. Jadi jawabannya berlawanan arah dengan gerak elektron." },
{ q: "Burung yang bertengger pada kabel tegangan tinggi tidak tersengat listrik karena ...", options: ["beda potensial antara kedua kakinya sangat kecil", "bulu burung adalah isolator sempurna", "arus listrik memilih lewat kabel saja", "burung tidak menyentuh kabel"], answer: 0, solution: "1. Arus mengalir jika ada beda potensial yang cukup di antara dua titik tubuh. 2. Kedua kaki burung menempel pada titik kabel yang hampir sama potensialnya sehingga beda potensialnya sangat kecil dan arus yang lewat tubuh burung dapat diabaikan. 3. Jadi jawabannya beda potensial antara kedua kakinya sangat kecil." },
{ q: "Kawat berhambatan $6\\ \\Omega$ dialiri arus $2\\ \\text{A}$. Daya disipasi pada kawat adalah ...", options: ["12 W", "24 W", "72 W", "3 W"], answer: 1, solution: "1. Diketahui $R = 6\\ \\Omega$ dan $I = 2\\ \\text{A}$. 2. Gunakan $P = I^2 R = 2^2 \\times 6 = 4 \\times 6 = 24\\ \\text{W}$. 3. Jadi jawabannya 24 W." },
{ q: "Tiga lampu identik $6\\ \\Omega$ dirangkai paralel lalu dihubungkan ke tegangan $12\\ \\text{V}$. Kuat arus total dari sumber adalah ...", options: ["2 A", "18 A", "0,67 A", "6 A"], answer: 3, solution: "1. Arus tiap lampu $I = \\frac{V}{R} = \\frac{12}{6} = 2\\ \\text{A}$. 2. Pada rangkaian paralel arus total adalah jumlah arus tiap cabang: $I_{total} = 3 \\times 2 = 6\\ \\text{A}$. 3. Jadi jawabannya 6 A." },
{ q: "Pada rangkaian paralel, besaran yang sama untuk setiap cabang adalah ...", options: ["kuat arus tiap cabang", "hambatan total lebih besar", "tegangan tiap cabang", "jika satu putus semua mati"], answer: 2, solution: "1. Pada rangkaian paralel semua cabang terhubung langsung ke kedua terminal sumber. 2. Akibatnya beda potensial (tegangan) pada setiap cabang sama dengan tegangan sumber, sedangkan arusnya terbagi. 3. Jadi jawabannya tegangan tiap cabang." },
{ q: "Muatan $2\\ \\mu\\ \\text{C}$ bergerak $3 \\times 10^4\\ \\text{m/s}$ tegak lurus medan magnet $0{,}5\\ \\text{T}$. Besar gaya Lorentz yang dialami muatan adalah ...", options: ["0,03 N", "0,3 N", "3 N", "30 N"], answer: 0, solution: "1. Diketahui $q = 2 \\times 10^{-6}\\ \\text{C}$, $v = 3 \\times 10^4\\ \\text{m/s}$, $B = 0{,}5\\ \\text{T}$, $\\theta = 90^\\circ$. 2. Gunakan $F = qvB\\sin\\theta = (2 \\times 10^{-6})(3 \\times 10^4)(0{,}5)(1) = 3 \\times 10^{-2} = 0{,}03\\ \\text{N}$. 3. Jadi jawabannya 0,03 N." },
{ q: "Kawat lurus panjang $0{,}5\\ \\text{m}$ dialiri arus $4\\ \\text{A}$ dan berada tegak lurus medan magnet $0{,}8\\ \\text{T}$. Gaya magnet pada kawat adalah ...", options: ["3,2 N", "1,6 N", "0,16 N", "16 N"], answer: 1, solution: "1. Diketahui $L = 0{,}5\\ \\text{m}$, $I = 4\\ \\text{A}$, $B = 0{,}8\\ \\text{T}$, $\\theta = 90^\\circ$. 2. Gunakan $F = BIL\\sin\\theta = 0{,}8 \\times 4 \\times 0{,}5 \\times 1 = 1{,}6\\ \\text{N}$. 3. Jadi jawabannya 1,6 N." },
{ q: "Kawat lurus panjang dialiri arus $5\\ \\text{A}$. Besar induksi magnet pada jarak $0{,}1\\ \\text{m}$ dari kawat adalah ...", options: ["$1\\times 10^{-6}\\ \\text{T}$", "$5\\times 10^{-6}\\ \\text{T}$", "$1\\times 10^{-5}\\ \\text{T}$", "$1\\times 10^{-4}\\ \\text{T}$"], answer: 2, solution: "1. Diketahui $I = 5\\ \\text{A}$ dan $a = 0{,}1\\ \\text{m}$. 2. Gunakan $B = \\frac{\\mu_0 I}{2\\pi a} = \\frac{2 \\times 10^{-7} \\times 5}{0{,}1} = 1 \\times 10^{-5}\\ \\text{T}$. 3. Jadi jawabannya $1\\times 10^{-5}\\ \\text{T}$." },
{ q: "Solenoida memiliki $500$ lilitan, panjang $0{,}25\\ \\text{m}$, dialiri arus $2\\ \\text{A}$. Induksi magnet di pusat solenoida adalah ... ($\\mu_0 = 4\\pi \\times 10^{-7}\\ \\text{Wb/Am}$)", options: ["50,3 mT", "0,503 mT", "16 mT", "5,03 mT"], answer: 3, solution: "1. Diketahui $N = 500$, $L = 0{,}25\\ \\text{m}$, $I = 2\\ \\text{A}$. 2. Gunakan $B = \\frac{\\mu_0 N I}{L} = \\frac{4\\pi \\times 10^{-7} \\times 500 \\times 2}{0{,}25} = 16\\pi \\times 10^{-4} = 5{,}03 \\times 10^{-3}\\ \\text{T} = 5{,}03\\ \\text{mT}$. 3. Jadi jawabannya 5,03 mT." },
{ q: "Fluks magnet yang menembus bidang seluas $0{,}05\\ \\text{m}^2$ yang tegak lurus medan magnet $0{,}4\\ \\text{T}$ adalah ...", options: ["0,02 Wb", "0,2 Wb", "2 Wb", "0,002 Wb"], answer: 0, solution: "1. Diketahui $B = 0{,}4\\ \\text{T}$, $A = 0{,}05\\ \\text{m}^2$, $\\theta = 0^\\circ$. 2. Gunakan $\\Phi = BA\\cos\\theta = 0{,}4 \\times 0{,}05 \\times 1 = 0{,}02\\ \\text{Wb}$. 3. Jadi jawabannya 0,02 Wb." },
{ q: "Kumparan $100$ lilitan mengalami perubahan fluks magnet $0{,}02\\ \\text{Wb}$ dalam $0{,}01\\ \\text{s}$. GGL induksi yang timbul adalah ...", options: ["2 V", "200 V", "2000 V", "20 V"], answer: 1, solution: "1. Diketahui $N = 100$, $\\Delta\\Phi = 0{,}02\\ \\text{Wb}$, $\\Delta t = 0{,}01\\ \\text{s}$. 2. Gunakan Hukum Faraday $\\varepsilon = -N\\frac{\\Delta\\Phi}{\\Delta t} = -100 \\times \\frac{0{,}02}{0{,}01} = -200\\ \\text{V}$. 3. Jadi besar GGL induksinya 200 V." },
{ q: "Sebuah transformator digunakan untuk menurunkan tegangan $220\\ \\text{V}$ menjadi $110\\ \\text{V}$. Perbandingan jumlah lilitan yang tepat adalah ...", options: ["Np > Ns", "Ns < Np", "Np = Ns", "tanpa lilitan"], answer: 1, solution: "1. Pada transformator berlaku $\\frac{V_p}{V_s} = \\frac{N_p}{N_s}$. 2. Karena $V_s < V_p$ (step-down), maka $N_s < N_p$; jumlah lilitan sekunder lebih sedikit daripada primer. 3. Jadi jawabannya Ns < Np." },
{ q: "Transformator ideal menurunkan tegangan $220\\ \\text{V}$ menjadi $110\\ \\text{V}$. Jika arus sekunder $4\\ \\text{A}$, arus primernya adalah ...", options: ["0,5 A", "8 A", "4 A", "2 A"], answer: 3, solution: "1. Diketahui $V_p = 220\\ \\text{V}$, $V_s = 110\\ \\text{V}$, $I_s = 4\\ \\text{A}$. 2. Pada trafo ideal $V_p I_p = V_s I_s$, sehingga $I_p = \\frac{110 \\times 4}{220} = 2\\ \\text{A}$. 3. Jadi jawabannya 2 A." },
{ q: "Menurut kaidah tangan kanan, arah gaya Lorentz pada muatan positif yang bergerak dalam medan magnet adalah ...", options: ["searah kecepatan muatan", "tegak lurus arah kecepatan dan arah medan magnet", "searah medan magnet", "berlawanan arah medan magnet"], answer: 1, solution: "1. Gaya Lorentz dirumuskan $\\vec{F} = q(\\vec{v} \\times \\vec{B})$. 2. Hasil perkalian silang selalu tegak lurus bidang yang dibentuk $\\vec{v}$ dan $\\vec{B}$, dengan arah mengikuti kaidah tangan kanan. 3. Jadi jawabannya tegak lurus arah kecepatan dan arah medan magnet." },
{ q: "GGL induksi dapat dibangkitkan pada kumparan dengan cara ...", options: ["magnet diam di dalam kumparan", "kumparan digerakkan memotong garis gaya magnet", "kumparan tanpa inti besi", "kawat tanpa arus listrik"], answer: 1, solution: "1. Menurut Hukum Faraday, GGL induksi timbul hanya jika ada perubahan fluks magnet yang menembus kumparan. 2. Menggerakkan kumparan memotong garis gaya magnet mengubah fluks yang menembusnya sehingga timbul GGL; magnet yang diam tidak mengubah fluks. 3. Jadi jawabannya kumparan digerakkan memotong garis gaya magnet." },
{ q: "Transformator hanya dapat bekerja pada arus bolak-balik (AC) karena ...", options: ["arus DC lebih berbahaya", "hanya arus bolak-balik menghasilkan fluks magnet yang berubah-ubah", "arus DC lebih mahal", "arus AC lebih kecil"], answer: 1, solution: "1. Prinsip transformator adalah induksi elektromagnetik antar kumparan melalui fluks magnet bersama. 2. GGL induksi memerlukan perubahan fluks ($\\varepsilon = -N\\Delta\\Phi/\\Delta t$); arus DC menghasilkan fluks tetap sehingga tidak ada GGL pada kumparan sekunder. 3. Jadi jawabannya hanya arus bolak-balik menghasilkan fluks magnet yang berubah-ubah." },
{ q: "Cahaya berpanjang gelombang $400\\ \\text{nm}$ menyinari logam dengan fungsi kerja $2\\ \\text{eV}$. Energi kinetik maksimum fotoelektron yang terlepas adalah ... ($hc = 1240\\ \\text{eV nm}$)", options: ["3,1 eV", "1,1 eV", "5,1 eV", "2 eV"], answer: 1, solution: "1. Diketahui $\\lambda = 400\\ \\text{nm}$, $W_0 = 2\\ \\text{eV}$. 2. Energi foton $E = \\frac{hc}{\\lambda} = \\frac{1240}{400} = 3{,}1\\ \\text{eV}$; gunakan persamaan fotolistrik $E_{k,maks} = E - W_0 = 3{,}1 - 2 = 1{,}1\\ \\text{eV}$. 3. Jadi jawabannya 1,1 eV." },
{ q: "Fungsi kerja suatu logam $4{,}4 \\times 10^{-19}\\ \\text{J}$. Frekuensi ambang logam tersebut adalah ... ($h = 6{,}6 \\times 10^{-34}\\ \\text{J s}$)", options: ["6,67x10^14 Hz", "6,67x10^15 Hz", "1,5x10^14 Hz", "4,4x10^14 Hz"], answer: 0, solution: "1. Diketahui $W_0 = 4{,}4 \\times 10^{-19}\\ \\text{J}$ dan $h = 6{,}6 \\times 10^{-34}\\ \\text{J s}$. 2. Gunakan $W_0 = hf_0$, sehingga $f_0 = \\frac{4{,}4 \\times 10^{-19}}{6{,}6 \\times 10^{-34}} = 0{,}667 \\times 10^{15} = 6{,}67 \\times 10^{14}\\ \\text{Hz}$. 3. Jadi jawabannya 6,67x10^14 Hz." },
{ q: "Pengamat di laboratorium mengukur selang waktu suatu kejadian di pesawat yang bergerak $0{,}8c$ sebesar $5\\ \\text{s}$. Menurut astronot di pesawat, selang waktu kejadian tersebut adalah ...", options: ["1,8 s", "5 s", "3 s", "4,2 s"], answer: 2, solution: "1. Waktu $5\\ \\text{s}$ yang diukur pengamat diam adalah waktu yang mengalami dilatasi; waktu sejati di pesawat $t_0$ lebih singkat. 2. Gunakan $t = \\frac{t_0}{\\sqrt{1 - v^2/c^2}}$, sehingga $t_0 = 5 \\times \\sqrt{1 - 0{,}64} = 5 \\times 0{,}6 = 3\\ \\text{s}$. 3. Jadi jawabannya 3 s." },
{ q: "Sebuah tongkat yang panjang diamnya $60\\ \\text{m}$ bergerak $0{,}6c$ relatif terhadap pengamat di Bumi. Panjang tongkat menurut pengamat Bumi adalah ...", options: ["60 m", "36 m", "48 m", "100 m"], answer: 2, solution: "1. Diketahui $L_0 = 60\\ \\text{m}$ dan $v = 0{,}6c$. 2. Gunakan kontraksi panjang $L = L_0\\sqrt{1 - v^2/c^2} = 60 \\times \\sqrt{1 - 0{,}36} = 60 \\times 0{,}8 = 48\\ \\text{m}$. 3. Jadi jawabannya 48 m." },
{ q: "Peristiwa efek fotolistrik menjadi bukti bahwa cahaya memiliki sifat ...", options: ["gelombang", "partikel", "tak bermassa", "selalu dipantulkan"], answer: 1, solution: "1. Pada efek fotolistrik, elektron terlepas seketika hanya jika frekuensi cahaya di atas frekuensi ambang, terlepas dari intensitasnya. 2. Hal ini hanya dapat dijelaskan jika cahaya terdiri atas paket-paket energi diskret (foton) yang menumbuk elektron, bukan gelombang kontinu. 3. Jadi jawabannya partikel." },
{ q: "Menurut model atom Bohr, energi elektron atom hidrogen pada kulit ke-3 adalah ... ($E_n = -13{,}6/n^2\\ \\text{eV}$)", options: ["-3,4 eV", "-6,8 eV", "-1,51 eV", "-13,6 eV"], answer: 2, solution: "1. Diketahui $n = 3$. 2. Gunakan $E_3 = \\frac{-13{,}6}{3^2} = \\frac{-13{,}6}{9} = -1{,}51\\ \\text{eV}$. 3. Jadi jawabannya -1,51 eV." },
{ q: "Menurut hipotesis de Broglie, jika momentum suatu partikel diperkecil maka panjang gelombang materinya menjadi ...", options: ["nol", "makin besar", "tetap", "makin kecil"], answer: 1, solution: "1. Panjang gelombang de Broglie dirumuskan $\\lambda = \\frac{h}{p}$. 2. Panjang gelombang berbanding terbalik dengan momentum, sehingga momentum yang diperkecil menghasilkan panjang gelombang yang makin besar. 3. Jadi jawabannya makin besar." },
{ q: "Spektrum garis pada atom hidrogen terjadi karena ...", options: ["elektron diam di dalam inti", "inti atom memancarkan elektron", "atom tidak memiliki energi", "elektron berpindah kulit sambil memancarkan atau menyerap foton"], answer: 3, solution: "1. Menurut Bohr, elektron hanya dapat menempati kulit-kulit dengan tingkat energi tertentu. 2. Saat elektron berpindah dari kulit tinggi ke rendah, selisih energinya dipancarkan sebagai foton dengan frekuensi khas, menghasilkan garis-garis spektrum diskret. 3. Jadi jawabannya elektron berpindah kulit sambil memancarkan atau menyerap foton." },

  ]
};
